 const DAY1_LESSONS={
  "preposition":{"title":"전치사를 넣을 자리와 넣지 않을 자리","rule":"introduce·explain·suggest·announce는 전달하는 내용을 목적어로 두고 듣는 사람은 to로 연결한다. 사람을 먼저 쓰는 4형식으로는 쓰지 않는다. 반대로 approach·discuss·enter·marry·reach·resemble·answer는 목적어를 바로 받는 타동사라 전치사를 넣지 않는다. wait처럼 목적어를 바로 받지 못하는 동사에는 for가 반드시 필요하다.","hook":"한국어 “~에게·~에”를 전치사로 그대로 옮기지 않기","examples":["The guide explained the rules to the visitors.","The reporter approached the mayor after the vote.","We are waiting for the results."]},
  "question-form":{"title":"간접의문문과 부가의문문","rule":"의문사절이 다른 동사의 목적어로 들어가면 의문사 + 주어 + 동사라는 평서문 어순이 되고, 의문문의 도치를 쓰지 않는다. 부가의문문은 주절의 주어와 동사에 맞춘다. 뒤에 딸린 that절의 주어와 동사에 맞추지 않는다.","hook":"안에 든 절은 평서문 어순 / 꼬리표는 주절 기준","examples":["I do not know when the office opens.","She thinks that he is honest, doesn’t she?"]},
  "linking":{"title":"2형식 동사 뒤의 보어","rule":"taste·smell·sound·look·feel처럼 감각을 나타내는 동사는 주어의 상태를 설명하므로 보어에 부사가 아니라 형용사를 쓴다. remain·stay처럼 상태가 이어짐을 말하는 동사도 보어를 두며, 주어가 동작을 받은 상태라면 과거분사를 보어로 쓴다.","hook":"주어를 설명하는 자리 → 형용사·과거분사","examples":["This soup tastes salty.","Please remain seated until the bus stops."]},
  "lookalike":{"title":"형태가 겹쳐서 헷갈리는 동사","rule":"lie(눕다·놓여 있다)는 lie-lay-lain으로 목적어가 없고, lay(놓다)는 lay-laid-laid로 목적어가 있다. lie의 과거형이 lay라서 두 동사가 겹쳐 보인다. find(찾다)는 find-found-found, found(설립하다)는 found-founded-founded다. 철자가 같아 보이는 지점에서 뜻과 목적어 유무를 확인한다.","hook":"lie의 과거가 lay / found는 서로 다른 두 동사","examples":["Infants lie face down when they sleep.","She laid the documents on the desk.","They founded the company in 1998."]},
  "no-passive":{"title":"수동태를 쓰지 않는 자리","rule":"rise(오르다)는 목적어가 없는 자동사라 수동태로 쓰지 않는다. 값을 올리는 타동사는 raise다. sell·read·wash처럼 일부 동사는 능동형 그대로 “잘 팔린다·잘 읽힌다”라는 수동의 뜻을 나타내며, 이때도 수동태로 바꾸지 않는다.","hook":"자동사 rise / 능동형으로 수동 뜻인 sell","examples":["Rents have risen sharply this year.","The landlord raised the rent again.","Her first novel sold surprisingly well."]},
  "gerund-only":{"title":"동명사만 목적어로 쓰는 동사","rule":"resist·admit·avoid·deny·mind·postpone·enjoy·finish는 목적어로 동명사를 쓰고 to부정사를 쓰지 않는다. 목적어가 동작을 받는 뜻이면 being + 과거분사 형태의 동명사가 된다.","hook":"이 동사들 뒤에는 -ing","examples":["He avoided answering the question.","They postponed announcing the result."]},
  "object-voice":{"title":"목적어가 동작을 받을 때의 보어","rule":"목적어가 동작을 직접 하면 목적격보어에 현재분사나 원형을 쓰고, 목적어가 동작을 받으면 과거분사를 쓴다. 형태는 앞의 동사가 정한다. see·hear·listen to 같은 지각동사와 keep·have는 과거분사를 바로 쓰고, let·make 같은 사역동사는 원형 자리에 be + 과거분사를 넣으며, want·expect는 to be + 과거분사를 쓴다.","hook":"목적어가 하는가 받는가 → 형태는 앞 동사가 결정","examples":["I saw the gate locked from the inside.","Keep me informed about the schedule.","Do not let the paint be exposed to sunlight.","I want this form to be signed today."]},
  "object-form":{"title":"동사가 정해 주는 목적어 뒤 형태","rule":"encourage·allow·advise·cause·force·persuade는 목적어 뒤에 to부정사를 쓴다. make·let·have는 원형부정사를 쓴다. keep·prevent·stop·discourage는 A from -ing로 “A가 ~하지 못하게 하다”를 나타낸다. 뜻이 비슷해도 동사마다 뒤에 오는 형태가 정해져 있다.","hook":"뜻이 아니라 동사별로 고정된 형태","examples":["The city encouraged residents to recycle.","The noise made everyone leave early.","The strike kept us from reaching the airport."]},
  "prep-pair":{"title":"A of B와 A as B 짝","rule":"accuse A of B는 “A를 B의 이유로 고발·비난하다”이며 of 뒤에는 명사나 -ing가 온다. think of A as B·regard A as B·refer to A as B는 “A를 B로 여기다·부르다”로 as가 짝이다. 동사마다 붙는 전치사가 정해져 있으므로 뜻이 비슷하다고 바꿔 쓰지 않는다.","hook":"이유는 of / 자격·명칭은 as","examples":["They accused the clerk of leaking the file.","Many people think of him as a pioneer."]},
  "infinitive-gerund":{"title":"to부정사와 동명사의 뜻 차이","rule":"forget·remember·regret·stop은 뒤에 오는 형태에 따라 뜻이 달라진다. to부정사는 앞으로 할 일이나 지금 하려는 목적을 가리키고, 동명사는 이미 한 일을 가리킨다. stop -ing는 하던 일을 그만두는 것이고, stop to do는 무엇을 하려고 잠시 멈추는 것이다.","hook":"to는 앞으로 할 일 / -ing는 이미 한 일","examples":["Do not forget to lock the door.","I regret telling her the truth.","He stopped to answer the phone."]},
  "finite":{"title":"명사의 전치사와 문장의 본동사","rule":"명사 demand는 무엇에 대한 수요인지를 for로 연결한다. 또 문장에는 반드시 본동사가 있어야 하므로, 주어부가 길어도 being·having 같은 분사가 서술어를 대신할 수 없다.","hook":"demand for ~ / 서술어는 분사가 아니라 정동사","examples":["The demand for electric cars is rising.","The reason for the delay was a broken signal box."]},
  "it-takes":{"title":"It takes 시간 to do","rule":"It takes + (사람) + 시간 + to부정사로 “~하는 데 시간이 걸린다”를 나타낸다. It은 가주어이고 실제 내용은 to부정사가 맡는다. 시간을 주어로 올려 수동태로 바꾸거나, to부정사 대신 for -ing를 쓰지 않는다.","hook":"가주어 It + take + 시간 + to do","examples":["It takes about ten minutes to walk there.","It took her three years to finish the thesis."]}
 };
 const DAY1=[
  {"n":1,"point":"4형식 불가(introduce/explain/suggest/announce + to)","lesson":"preposition","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["The host introduced the guest speaker to the audience.","The pharmacist explained me how to take the new tablets.","We reached the harbor just as the morning fog began to lift.","The passengers were waiting for the shuttle in the pouring rain."],"correctIndex":1,"explanation":"정답 근거: explain은 설명하는 내용을 목적어로 두고, 듣는 사람은 to로 연결한다. 사람을 바로 목적어로 쓰는 4형식(explain me ~)은 쓰지 않으므로 explained to me how to take the new tablets로 고친다.\n\n보기 비교: ① introduce A to B로 소개할 사람을 목적어, 듣는 사람을 to로 연결해 옳다. ③ reach는 전치사 없이 목적어를 받는 타동사라 reached the harbor가 옳다. ④ wait는 목적어를 바로 받지 못하므로 waiting for the shuttle이 옳다.\n\n기억 연결: explain · introduce · suggest · announce → “~에게”는 늘 to + 사람. explain me(X) / explain to me(O)."},
  {"n":2,"point":"4형식 불가(introduce/explain/suggest/announce + to)","lesson":"preposition","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["The chairman announced the staff the merger on Monday.","She suggested me a quicker route to the train station.","Let me introduce you my cousin who lives in Toronto.","The clerk explained the refund policy to the customer."],"correctIndex":3,"explanation":"정답 근거: explain은 설명하는 내용(the refund policy)을 목적어로 두고 듣는 사람(the customer)을 to로 연결했으므로 옳다.\n\n보기 비교: ① announce도 4형식을 쓰지 않으므로 announced the merger to the staff로 고친다. ② suggest도 suggested a quicker route to me로 고친다. ③ introduce도 사람을 먼저 쓰지 않으므로 introduce my cousin ... to you로 고친다.\n\n기억 연결: announce · suggest · introduce · explain → 내용이 먼저, 사람은 뒤에 to로. “give처럼 사람을 앞에 두는” 동사가 아니다."},
  {"n":3,"point":"타동사에 전치사 금지","lesson":"preposition","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["A stranger approached to our table and asked for directions.","The committee will discuss the proposed budget cuts next Tuesday.","My younger daughter resembles her grandmother more every year.","Nobody answered the phone at the front desk last night."],"correctIndex":0,"explanation":"정답 근거: approach는 목적어를 바로 받는 타동사다. 한국어 “테이블로 다가왔다”에 끌려 to를 넣으면 틀리므로 approached our table로 고친다.\n\n보기 비교: ② discuss도 전치사 없이 목적어(the budget cuts)를 받아 옳다. ③ resemble도 resembles her grandmother로 옳다. ④ answer도 answered the phone으로 옳다.\n\n기억 연결: approach → 바로 목적어. approach to(X). 같은 무리: discuss · enter · marry · reach · resemble · answer."},
  {"n":4,"point":"타동사에 전치사 금지","lesson":"preposition","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["Two security guards entered the empty lobby at midnight.","The panel discussed the new safety standards for an hour.","The hikers finally reached at the mountain cabin after sunset.","The famous actress married a young pilot she had met in Lisbon."],"correctIndex":2,"explanation":"정답 근거: reach는 도착 지점을 바로 목적어로 받는 타동사다. arrive at과 섞어 at을 넣으면 틀리므로 reached the mountain cabin으로 고친다.\n\n보기 비교: ① enter는 entered the lobby처럼 전치사 없이 옳다. ② discuss도 discussed the standards로 옳다. ④ marry도 married a pilot으로 옳다.\n\n기억 연결: reach → 바로 목적어(reach the cabin). 전치사가 필요한 것은 arrive at · get to 쪽이다."},
  {"n":5,"point":"타동사에 전치사 금지","lesson":"preposition","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["The small plane approached the runway through heavy rain.","The lawyers discussed the terms of the contract in private.","It takes about ten minutes to reach the station on foot.","My uncle married with a nurse from the local hospital."],"correctIndex":3,"explanation":"정답 근거: marry는 결혼 상대를 바로 목적어로 받는 타동사라 with를 넣지 않는다. married a nurse로 고친다.\n\n보기 비교: ① approach는 approached the runway로 옳다. ② discuss도 discussed the terms로 옳다. ③ It takes + 시간 + to부정사 구조이고, reach도 the station을 바로 목적어로 받아 옳다.\n\n기억 연결: marry → 바로 목적어(marry a nurse). 상태를 말할 때만 be married to. marry with(X)."},
  {"n":6,"point":"타동사에 전치사 금지","lesson":"preposition","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["The twins resemble with each other in their voices.","We discussed about the new work schedule over lunch.","The office answered every complaint within a week.","The young deer approached to the fence very slowly."],"correctIndex":2,"explanation":"정답 근거: answer는 목적어를 바로 받는 타동사이므로 answered every complaint가 옳다.\n\n보기 비교: ① resemble은 전치사 없이 resemble each other로 고친다. ② discuss도 discussed the new work schedule로 고친다(about 삭제). ④ approach도 approached the fence로 고친다.\n\n기억 연결: resemble · discuss · approach · answer → “~와 · ~에 대해 · ~에게”라는 한국어에 속지 말고 전치사 없이."},
  {"n":7,"point":"부가의문문(주절 기준)","lesson":"question-form","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["You think the museum opens at nine, don’t you?","The guests have already left the hotel, haven’t they?","She believes that the plan will work, won’t it?","Your brother seldom calls home these days, does he?"],"correctIndex":2,"explanation":"정답 근거: 부가의문문은 주절 She believes에 맞춘다. 일반동사 현재 3인칭 단수 긍정이므로 doesn’t she로 고친다. that절의 the plan will work에 맞춘 won’t it은 틀리다.\n\n보기 비교: ① 주절 You think에 맞춘 don’t you라 옳다. ② 현재완료 긍정이라 haven’t they가 옳다. ④ seldom이 이미 부정의 뜻이라 긍정형 does he가 옳다.\n\n기억 연결: believe · think · say + that절 → 꼬리는 앞의 주어(She believes → doesn’t she)에 붙인다."},
  {"n":8,"point":"remain + p.p.","lesson":"linking","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["Please remain seating until the pilot turns off the sign.","The museum remained closed for repairs during the whole winter.","The fresh coffee smells wonderful this morning.","The unopened letter lay on his desk for a week."],"correctIndex":0,"explanation":"정답 근거: 승객은 좌석에 앉혀진 상태로 있어야 하므로 remain 뒤에 과거분사 seated를 쓴다. remain seating으로는 쓰지 않으므로 remain seated로 고친다.\n\n보기 비교: ② 박물관이 닫힌 상태로 있었으므로 remained closed가 옳다. ③ smell 뒤에 형용사 wonderful을 쓴 2형식이라 옳다. ④ lay는 자동사 lie(놓여 있다)의 과거형이라 옳다.\n\n기억 연결: remain · stay + 상태 → seated · closed처럼 과거분사. “자리에 앉아 계세요” = remain seated."},
  {"n":9,"point":"lie/lay","lesson":"lookalike","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["She laid a clean towel over the chair to dry.","The workers have lain new tiles in the bathroom.","These documents have lain in the safe since 1990.","The hens laid fewer eggs during the cold spell."],"correctIndex":1,"explanation":"정답 근거: new tiles라는 목적어가 있으므로 “놓다·깔다”인 타동사 lay를 써야 하고, 그 과거분사는 laid다. have laid new tiles로 고친다. lain은 목적어가 없는 자동사 lie의 과거분사다.\n\n보기 비교: ① a clean towel이라는 목적어가 있어 laid가 옳다. ③ 서류가 스스로 놓여 있는 것이라 자동사 lie의 과거분사 lain이 옳다. ④ lay eggs(알을 낳다)의 과거형 laid라 옳다.\n\n기억 연결: lay-laid-laid(목적어 O) / lie-lay-lain(목적어 X). 목적어가 보이면 laid."},
  {"n":10,"point":"lie/lay","lesson":"lookalike","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["The old dog lay in the shade all afternoon.","He lay the heavy box down on the kitchen floor.","Your phone has laid on the counter since breakfast.","I usually lay on the sofa after a long night shift."],"correctIndex":0,"explanation":"정답 근거: 눕는 동작에는 목적어가 없으므로 자동사 lie를 쓰고, 과거 이야기라 과거형 lay가 옳다.\n\n보기 비교: ② the heavy box라는 목적어가 있으므로 타동사 lay의 과거형 laid로 고친다. ③ 전화기가 스스로 놓여 있는 것이라 has lain으로 고친다. ④ 습관적으로 눕는 것이므로 자동사 lie의 현재형 lie로 고친다.\n\n기억 연결: lie(눕다) → lay(과거) → lain / lay(놓다) → laid → laid. “과거 lay”와 “현재 lay”를 목적어로 구별."},
  {"n":11,"point":"found/find","lesson":"lookalike","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["Her grandmother founded a small bakery in 1952.","Rescuers found the missing hiker near a frozen stream.","The two brothers founded the lost key under the rug.","The river rose quickly after three days of heavy rain."],"correctIndex":2,"explanation":"정답 근거: 잃어버린 열쇠는 “설립하는” 대상이 아니라 “찾는” 대상이므로 find의 과거형 found를 써서 found the lost key로 고친다.\n\n보기 비교: ① 빵집을 세웠다는 뜻이라 found(설립하다)의 과거형 founded가 옳다. ② 등산객을 찾았다는 뜻이라 find의 과거형 found가 옳다. ④ rise(오르다)의 과거형 rose라 옳다.\n\n기억 연결: find-found-found(찾다) / found-founded-founded(설립하다). 회사 · 학교 · 가게면 founded, 물건 · 사람이면 found."},
  {"n":12,"point":"능동형 수동 의미(sell/read/wash)","lesson":"no-passive","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["The new phone model sells well among teenagers.","The price of eggs has been risen again this month.","She laid down on the bed as soon as she got home.","They introduced us their new business partner."],"correctIndex":0,"explanation":"정답 근거: sell은 주어가 상품일 때 능동형 그대로 “잘 팔린다”라는 뜻을 나타내므로 sells well이 옳다.\n\n보기 비교: ② rise는 자동사라 수동태가 없으므로 has risen으로 고친다. ③ 목적어 없이 눕는 것이므로 lay down(lie의 과거)으로 고친다. ④ introduce는 4형식을 쓰지 않으므로 introduced their new business partner to us로 고친다.\n\n기억 연결: sell · read · wash + well/easily → 능동형으로 “잘 팔린다 · 잘 읽힌다 · 잘 빨린다”."},
  {"n":13,"point":"능동형 수동 의미(sell/read/wash)","lesson":"no-passive","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["The tenants resisted to leave their old apartments.","This cotton shirt washes well even in cold water.","The heavy fog caused the ferry leave two hours late.","The rain prevented us to finish the soccer game."],"correctIndex":1,"explanation":"정답 근거: wash는 주어가 옷감일 때 능동형 그대로 “세탁이 잘된다”라는 뜻을 나타내므로 washes well이 옳다.\n\n보기 비교: ① resist는 동명사를 목적어로 쓰므로 resisted leaving으로 고친다. ③ cause는 목적어 뒤에 to부정사를 쓰므로 caused the ferry to leave로 고친다. ④ prevent는 A from -ing이므로 prevented us from finishing으로 고친다.\n\n기억 연결: wash · sell · read → 사물 주어 + 능동형 + well = 수동의 뜻. 굳이 is washed로 바꾸지 않는다."},
  {"n":14,"point":"rise/raise(수동 불가)","lesson":"no-passive","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["The landlord raised the rent by five percent.","Sea levels have risen steadily over the past century.","Several parents raised concerns about the lunch menu.","Bus fares were risen twice during the last year."],"correctIndex":3,"explanation":"정답 근거: rise는 목적어가 없는 자동사라 수동태가 없다. 요금이 올랐다면 rose, 누군가 올렸다는 뜻이라면 타동사 raise를 써서 were raised로 고친다.\n\n보기 비교: ① the rent라는 목적어가 있어 타동사 raised가 옳다. ② 해수면이 스스로 오른 것이라 자동사 rise의 현재완료 have risen이 옳다. ③ concerns를 목적어로 받는 타동사 raised(제기하다)라 옳다.\n\n기억 연결: rise-rose-risen(자동사, be risen 불가) / raise-raised-raised(타동사, be raised 가능)."},
  {"n":15,"point":"간접의문문 어순","lesson":"question-form","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["Can you tell me where the nearest pharmacy is?","Nobody knows who will replace the head coach.","I have no idea why is the printer jammed again.","We asked the guide how long the tour would last."],"correctIndex":2,"explanation":"정답 근거: why절이 idea 뒤에 들어간 간접의문문이므로 의문사 + 주어 + 동사 어순을 써서 why the printer is jammed again으로 고친다.\n\n보기 비교: ① where the nearest pharmacy is로 평서문 어순이라 옳다. ② who가 절의 주어라 who will replace가 그대로 옳다. ④ how long the tour would last로 평서문 어순이라 옳다.\n\n기억 연결: know · wonder · tell me · have no idea + 의문사 → 그 뒤는 “주어 + 동사”. why is it(X) → why it is(O)."},
  {"n":16,"point":"resist/admit/avoid/deny/mind/postpone + -ing","lesson":"gerund-only","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["We postponed to paint the fence until the weather cleared.","The minister denied receiving any money from the building firm.","I don’t mind waiting outside while you finish your call.","The boy finally admitted breaking the neighbor’s window."],"correctIndex":0,"explanation":"정답 근거: postpone은 동명사만 목적어로 쓰므로 postponed painting the fence로 고친다.\n\n보기 비교: ② deny는 동명사를 목적어로 쓰므로 denied receiving이 옳다. ③ mind도 동명사를 쓰므로 mind waiting이 옳다. ④ admit도 동명사를 쓰므로 admitted breaking이 옳다.\n\n기억 연결: postpone · deny · mind · admit · avoid · resist → 뒤는 -ing. “미루다”도 to가 아니라 -ing."},
  {"n":17,"point":"resist/admit/avoid/deny/mind/postpone + -ing","lesson":"gerund-only","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["She could not resist tasting the cake before dinner.","The mayor postponed signing the new budget plan.","The singer denied having canceled the concert.","He avoided to make eye contact with the interviewer."],"correctIndex":3,"explanation":"정답 근거: avoid는 동명사만 목적어로 쓰므로 avoided making eye contact로 고친다.\n\n보기 비교: ① resist는 동명사를 쓰므로 resist tasting이 옳다. ② postpone도 postponed signing으로 옳다. ③ deny 뒤에 완료 동명사 having canceled를 써서 이전의 일을 부인한 것이라 옳다.\n\n기억 연결: avoid → -ing(avoid making). resist · postpone · deny도 같은 무리."},
  {"n":18,"point":"resist/admit/avoid/deny/mind/postpone + -ing","lesson":"gerund-only","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["The suspect admitted to steal the famous painting.","The prisoner resisted being moved to another cell.","Would you mind to hold the door open for me?","The company postponed to launch the app until May."],"correctIndex":1,"explanation":"정답 근거: resist는 동명사를 목적어로 쓰고, 죄수가 옮겨지는 쪽이므로 수동 동명사 being moved가 옳다.\n\n보기 비교: ① admit은 admitted stealing 또는 admitted to stealing으로 고친다(이때 to는 전치사). ③ mind는 mind holding으로 고친다. ④ postpone은 postponed launching으로 고친다.\n\n기억 연결: resist · admit · mind · postpone → -ing. 당하는 쪽이면 being + p.p.(resisted being moved)."},
  {"n":19,"point":"지각동사/keep/have + p.p.","lesson":"object-voice","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["I heard the church bells ringing in the distance.","She had her hair cut short before the wedding.","Please keep the windows closed during the storm.","We watched the old bridge demolishing by a crane."],"correctIndex":3,"explanation":"정답 근거: 다리는 크레인에 의해 철거되는 대상이므로 지각동사 watch + 목적어 + 과거분사를 써서 watched the old bridge demolished by a crane으로 고친다.\n\n보기 비교: ① 종이 스스로 울리므로 현재분사 ringing이 옳다. ② 머리카락은 잘리는 대상이라 have + O + p.p.(cut)가 옳다. ③ 창문은 닫히는 대상이라 keep + O + p.p.(closed)가 옳다.\n\n기억 연결: watch · hear · see · keep · have + O → O가 “당하면” p.p., “하면” -ing. by가 보이면 p.p."},
  {"n":20,"point":"지각동사/keep/have + p.p.","lesson":"object-voice","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["I saw the thief arresting by two police officers.","He kept the engine run while we loaded the van.","We heard the announcement made over the speakers.","She had her car repair at the garage down the street."],"correctIndex":2,"explanation":"정답 근거: 안내 방송은 “나오게 되는” 대상이므로 지각동사 hear + 목적어 + 과거분사 made가 옳다.\n\n보기 비교: ① 도둑은 체포되는 대상이므로 saw the thief arrested로 고친다. ② 엔진이 계속 돌아가는 것이므로 kept the engine running으로 고친다. ④ 차는 수리되는 대상이므로 had her car repaired로 고친다.\n\n기억 연결: see · hear · keep · have + O + (당하면 p.p. / 하면 -ing). 원형(run · repair)은 이 자리에 오지 않는다."},
  {"n":21,"point":"let + O + be p.p.","lesson":"object-voice","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["Don’t let the children be left alone near the pool.","The storm forced the school to close for two days.","The owner let the old wall paint by local volunteers.","The coach let the injured player rest on the bench for a while."],"correctIndex":2,"explanation":"정답 근거: 벽은 칠해지는 대상이다. let 뒤에는 원형이 오므로 원형 자리에 be + p.p.를 넣어 let the old wall be painted by local volunteers로 고친다.\n\n보기 비교: ① 아이들이 남겨지는 대상이라 let + O + be left가 옳다. ② force는 목적어 뒤에 to부정사를 쓰므로 forced the school to close가 옳다. ④ 선수가 스스로 쉬는 것이라 let + O + 원형 rest가 옳다.\n\n기억 연결: let + O + 원형 / O가 당하면 let + O + be p.p. (let it be painted)."},
  {"n":22,"point":"want/expect + O + to be p.p.","lesson":"object-voice","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["The client wants the logo design be changed again.","The manager expects the report to be finished by noon.","I want these boxes to be moved before the painters arrive.","We expect the new bridge to open to traffic next spring."],"correctIndex":0,"explanation":"정답 근거: want는 목적어 뒤에 to부정사를 쓰고, 로고 디자인은 바뀌는 대상이므로 to be + p.p.가 필요하다. wants the logo design to be changed로 고친다.\n\n보기 비교: ② expect + O + to be finished라 옳다. ③ want + O + to be moved라 옳다. ④ 다리가 스스로 개통하는 것이므로 능동 to부정사 to open이 옳다.\n\n기억 연결: want · expect + O + to. O가 당하면 to be p.p. — let과 달리 to를 빼지 않는다."},
  {"n":23,"point":"encourage/allow/advise/cause/force/persuade + O + to","lesson":"object-form","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["My doctor advised me to cut down on salty food.","Her parents persuaded her to apply for the scholarship.","The strike caused many morning flights to be canceled.","The zoo does not allow visitors feed the animals."],"correctIndex":3,"explanation":"정답 근거: allow는 목적어 뒤에 to부정사를 쓰므로 allow visitors to feed the animals로 고친다.\n\n보기 비교: ① advise + O + to cut이라 옳다. ② persuade + O + to apply라 옳다. ③ cause + O + to be canceled로, 항공편이 취소되는 대상이라 수동 to부정사가 옳다.\n\n기억 연결: allow · advise · persuade · cause · encourage · force + O + to. 사역동사처럼 원형을 쓰지 않는다."},
  {"n":24,"point":"encourage/allow/advise/cause/force/persuade + O + to","lesson":"object-form","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["The teacher encouraged the shy students speak up in class.","The flood forced hundreds of families to leave their homes.","My coach advised me not to skip the warm-up exercises.","The noise stopped me from concentrating on my book."],"correctIndex":0,"explanation":"정답 근거: encourage는 목적어 뒤에 to부정사를 쓰므로 encouraged the shy students to speak up으로 고친다.\n\n보기 비교: ② force + O + to leave라 옳다. ③ advise + O + not to skip으로, 부정어 not은 to 앞에 둔다. ④ stop A from -ing라 옳다.\n\n기억 연결: encourage → O + to do. “격려해서 하게 하다”라도 make처럼 원형을 쓰지 않는다."},
  {"n":25,"point":"encourage/allow/advise/cause/force/persuade + O + to","lesson":"object-form","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["The guard forced the drivers stop at the gate.","Mom will not allow us stay up past midnight.","The heavy traffic caused us to miss the first act.","The salesman persuaded my father buying a new car."],"correctIndex":2,"explanation":"정답 근거: cause는 목적어 뒤에 to부정사를 쓰므로 caused us to miss가 옳다.\n\n보기 비교: ① force는 forced the drivers to stop으로 고친다. ② allow는 allow us to stay up으로 고친다. ④ persuade는 persuaded my father to buy로 고친다.\n\n기억 연결: cause · force · allow · persuade → O + to do. 원형(stop)도 -ing(buying)도 아니다."},
  {"n":26,"point":"make/let/have + 원형","lesson":"object-form","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["The sad ending made the whole audience cry.","The officer had the driver to show his license.","Please let me know when the parcel arrives.","The bright sunlight kept us from seeing the screen."],"correctIndex":1,"explanation":"정답 근거: 사역동사 have는 목적어가 직접 하는 동작을 원형부정사로 쓴다. had the driver show his license로 고친다.\n\n보기 비교: ① make + O + 원형 cry라 옳다. ③ let + O + 원형 know라 옳다. ④ keep A from -ing라 옳다.\n\n기억 연결: make · let · have + O + 원형. have the driver show(O) / to show(X)."},
  {"n":27,"point":"make/let/have + 원형","lesson":"object-form","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["Her silly jokes always make me to laugh.","Let the kids to choose their own snacks.","The coach made us running around the field.","I had the plumber fix the leaking pipe."],"correctIndex":3,"explanation":"정답 근거: have + 목적어 + 원형부정사로, 배관공이 직접 고치는 것이라 원형 fix가 옳다.\n\n보기 비교: ① make는 make me laugh로 고친다. ② let은 Let the kids choose로 고친다. ③ make는 made us run으로 고친다.\n\n기억 연결: make · let · have → O 뒤에 to도 -ing도 없이 원형(laugh · choose · run · fix)."},
  {"n":28,"point":"keep/prevent/stop A from -ing","lesson":"object-form","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["Heavy snow prevented the plane to take off on time.","The fence keeps the deer from entering the garden.","A bad cold stopped her from joining the trip.","The new law discourages companies from dumping waste."],"correctIndex":0,"explanation":"정답 근거: prevent는 A from -ing로 “A가 ~하지 못하게 하다”를 나타낸다. prevented the plane from taking off로 고친다.\n\n보기 비교: ② keep A from -ing라 옳다. ③ stop A from -ing라 옳다. ④ discourage A from -ing도 같은 짝이라 옳다.\n\n기억 연결: prevent · keep · stop · discourage + A + from -ing. “못 하게”가 보이면 from."},
  {"n":29,"point":"감각동사 + 형용사","lesson":"linking","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["The milk smells sour, so please don’t drink it.","The homemade soup tasted deliciously after the hike.","Your idea for the party sounds great to me.","The children looked very tired after the long drive home."],"correctIndex":1,"explanation":"정답 근거: taste는 주어(soup)의 상태를 설명하는 감각동사라 보어에 형용사를 쓴다. tasted delicious로 고친다.\n\n보기 비교: ① smell 뒤에 형용사 sour라 옳다. ③ sound 뒤에 형용사 great라 옳다. ④ look 뒤에 형용사 tired라 옳다.\n\n기억 연결: taste · smell · sound · look · feel → 뒤는 형용사(delicious). -ly를 붙이지 않는다."},
  {"n":30,"point":"감각동사 + 형용사","lesson":"linking","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["The mountain air smells freshly after the rain.","The lake water felt coldly on my bare feet.","The plan sounds reasonably to most of us.","Your new haircut looks great in these photos."],"correctIndex":3,"explanation":"정답 근거: look은 주어(haircut)의 상태를 설명하는 감각동사이고 보어에 형용사 great를 썼으므로 옳다.\n\n보기 비교: ① smell은 smells fresh로 고친다. ② feel은 felt cold로 고친다. ③ sound는 sounds reasonable로 고친다.\n\n기억 연결: smell · feel · sound · look + 형용사. fresh · cold · reasonable · great."},
  {"n":31,"point":"accuse A of B","lesson":"prep-pair","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["The coach accused the referee of favoring the home team.","Critics regard the novel as a modern classic.","She accused her roommate for eating her lunch.","The report blamed the delay on bad weather."],"correctIndex":2,"explanation":"정답 근거: accuse는 비난 · 고발의 이유를 of로 연결한다. accused her roommate of eating her lunch로 고친다. for를 쓰는 짝은 blame A for B다.\n\n보기 비교: ① accuse A of -ing라 옳다. ② regard A as B라 옳다. ④ blame B on A(탓을 ~에게 돌리다)라 옳다.\n\n기억 연결: accuse → of (accuse A of B). blame → for / on. 둘을 섞지 않는다."},
  {"n":32,"point":"think of/regard/refer to A as B","lesson":"prep-pair","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["Most doctors regard sleep as part of good health.","Locals refer the old tower as the Needle.","Many fans think of him as the best goalkeeper ever.","The mayor accused the contractor of wasting money."],"correctIndex":1,"explanation":"정답 근거: refer는 “~을 …라고 부르다”일 때 refer to A as B로 쓴다. to가 빠졌으므로 refer to the old tower as the Needle로 고친다.\n\n보기 비교: ① regard A as B라 옳다. ③ think of A as B라 옳다. ④ accuse A of -ing라 옳다.\n\n기억 연결: refer to A as B · regard A as B · think of A as B → 짝은 as. refer는 to까지 한 덩어리."},
  {"n":33,"point":"think of/regard/refer to A as B","lesson":"prep-pair","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["They think of their dog for a member of the family.","The police accused the man with stealing a bike.","We regard honesty as the most important value.","The staff refer to the old printer for the dinosaur."],"correctIndex":2,"explanation":"정답 근거: regard A as B로 A를 B로 여긴다는 뜻이라 regard honesty as가 옳다.\n\n보기 비교: ① think of A as B이므로 think of their dog as a member로 고친다. ② accuse는 of와 짝이라 accused the man of stealing으로 고친다(with는 charge A with B). ④ refer to A as B이므로 refer to the old printer as the dinosaur로 고친다.\n\n기억 연결: regard · think of · refer to → as. accuse → of. for · with로 바꾸지 않는다."},
  {"n":34,"point":"forget/remember/regret/stop + to vs -ing","lesson":"infinitive-gerund","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["Don’t forget to water the plants while I’m away.","I still remember riding my first bike in the park.","The old man stopped to rest on a quiet bench by the lake.","I regret to tell her the secret at the party last week."],"correctIndex":3,"explanation":"정답 근거: 지난주에 이미 말해 버린 일을 후회하는 것이므로 regret -ing를 써서 regret telling her the secret으로 고친다. regret to do는 “~하게 되어 유감이다”라며 지금 전하는 말에 쓴다.\n\n보기 비교: ① 앞으로 할 일이라 forget to water가 옳다. ② 이미 한 일을 기억하므로 remember riding이 옳다. ③ 쉬려고 멈춘 것이라 목적의 stopped to rest가 옳다.\n\n기억 연결: regret · forget · remember → to는 앞으로 할 일, -ing는 이미 한 일. last week가 보이면 -ing."},
  {"n":35,"point":"forget/remember/regret/stop + to vs -ing","lesson":"infinitive-gerund","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["Remember turning off the gas before you go to bed.","We regret to announce that the flight has been canceled.","She will never forget seeing the ocean for the first time.","My father stopped smoking ten years ago."],"correctIndex":0,"explanation":"정답 근거: 잠자리에 들기 전에 앞으로 할 일을 기억하라는 뜻이므로 Remember to turn off the gas로 고친다.\n\n보기 비교: ② 지금 알리는 소식이 유감이라는 뜻이라 regret to announce가 옳다. ③ 이미 본 경험이라 forget seeing이 옳다. ④ 피우던 담배를 끊었으므로 stopped smoking이 옳다.\n\n기억 연결: remember → before you go(앞으로)면 to, 지난 경험이면 -ing. stop -ing = 그만두다."},
  {"n":36,"point":"forget/remember/regret/stop + to vs -ing","lesson":"infinitive-gerund","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["I’ll never forget to visit Rome with you last spring.","Please remember calling your grandmother tomorrow.","She regrets to quit her job at the bank two years ago.","On the way home, he stopped to pick up some milk."],"correctIndex":3,"explanation":"정답 근거: 집에 오는 길에 우유를 사려고 멈춘 것이므로 목적을 나타내는 stopped to pick up이 옳다.\n\n보기 비교: ① 지난봄에 이미 다녀온 일이므로 forget visiting으로 고친다. ② 내일 할 일이므로 remember to call로 고친다. ③ 2년 전 이미 그만둔 일을 후회하므로 regrets quitting으로 고친다.\n\n기억 연결: stop to do = ~하려고 멈추다 / stop -ing = 그만두다. forget · remember · regret은 시간 표시(last spring · tomorrow)로 판단."},
  {"n":37,"point":"demand/reason/need for","lesson":"finite","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["There is a growing demand for skilled nurses.","The reason of his absence was a family emergency.","The need for clean water is urgent in the region.","It took the crew two days to fix the burst pipe."],"correctIndex":1,"explanation":"정답 근거: 명사 reason은 무엇에 대한 이유인지를 for로 연결한다. The reason for his absence로 고친다.\n\n보기 비교: ① demand for skilled nurses라 옳다. ③ need for clean water라 옳다. ④ It takes + 사람 + 시간 + to부정사라 옳다.\n\n기억 연결: 명사 demand · reason · need → for. reason of(X)."},
  {"n":38,"point":"분사가 본동사 대신 불가","lesson":"finite","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["The man standing by the door is my new neighbor.","Most of the guests invited to the party arrived very late.","The results of the survey being surprising to everyone.","This short novel reads easily in a single evening."],"correctIndex":2,"explanation":"정답 근거: 문장에 본동사가 없다. 분사 being은 서술어가 될 수 없으므로 The results of the survey were surprising to everyone으로 고친다.\n\n보기 비교: ① standing은 man을 꾸미는 분사이고 본동사 is가 따로 있어 옳다. ② invited는 guests를 꾸미고 본동사 arrived가 있어 옳다. ④ read가 능동형으로 “잘 읽힌다”는 뜻의 본동사라 옳다.\n\n기억 연결: being · having이 주어 뒤에서 끝나면 → 본동사 is · are · was · were · has로 바꾼다."},
  {"n":39,"point":"분사가 본동사 대신 불가","lesson":"finite","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["The students in the back row having trouble hearing.","Every seat in the new theater being very comfortable.","The box sent from Busan arrived early this morning.","The price of the tickets including a free drink."],"correctIndex":2,"explanation":"정답 근거: sent from Busan은 box를 꾸미는 분사구이고, 본동사 arrived가 따로 있으므로 옳다.\n\n보기 비교: ① 본동사가 없으므로 are having trouble 또는 have trouble로 고친다. ② 본동사가 없으므로 is very comfortable로 고친다. ④ 본동사가 없으므로 includes a free drink로 고친다.\n\n기억 연결: 주어가 길어도 본동사 하나는 꼭 필요. having · being · including(-ing)으로 끝나면 문장이 아니다."},
  {"n":40,"point":"It takes (사람) 시간 to do","lesson":"it-takes","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["It took she almost an hour to find a parking space.","It took us three hours to climb the steep hill.","It takes about a month to learn the basic rules.","It will take the builders a year to finish the tower."],"correctIndex":0,"explanation":"정답 근거: It takes + 사람 + 시간 + to부정사에서 사람은 take의 목적어라 목적격을 쓴다. It took her almost an hour로 고친다.\n\n보기 비교: ② 목적격 us라 옳다. ③ 사람을 생략하고 시간 + to부정사만 쓴 형태라 옳다. ④ the builders가 사람 자리, a year가 시간 자리라 옳다.\n\n기억 연결: It takes + me · us · her(목적격) + 시간 + to do. take 뒤에 she · they(X)."},
  {"n":41,"point":"4형식 불가(introduce/explain/suggest/announce + to)","lesson":"preposition","type":"text","question":"“그 항공사는 승객들에게 출발 지연을 알렸다.”\nThe airline announced the delay ___ the passengers.\n빠진 한 단어를 쓰세요.","answers":["to"],"explanation":"정답 근거: announce는 알리는 내용(the delay)을 목적어로 두고 듣는 사람은 to로 연결하므로 to가 들어간다.\n\n보기 비교: announced the passengers the delay처럼 사람을 먼저 쓰는 4형식은 쓰지 않는다. for나 at도 아니다.\n\n기억 연결: announce · explain · introduce · suggest → 내용 + to + 사람."},
  {"n":42,"point":"타동사에 전치사 금지","lesson":"preposition","type":"text","question":"“그 학생은 종이 울린 뒤 조용히 교실에 들어갔다.”\nThe student quietly ___ the classroom after the bell.\nenter를 과거형으로 쓰고, 전치사가 필요하면 함께 쓰세요.","answers":["entered"],"explanation":"정답 근거: enter는 들어가는 장소를 바로 목적어로 받는 타동사라 전치사 없이 entered 한 단어만 쓴다.\n\n보기 비교: “교실에”라는 한국어 때문에 entered in이나 entered into를 쓰면 틀린다.\n\n기억 연결: enter → 바로 목적어(enter the room). approach · reach · marry · resemble · discuss · answer도 같다."},
  {"n":43,"point":"wait for","lesson":"preposition","type":"text","question":"“우리는 비가 그치기를 30분째 기다리고 있다.”\nWe have been ___ the rain to stop for half an hour.\nwait를 -ing형으로 쓰고, 전치사가 필요하면 함께 쓰세요.","answers":["waiting for"],"explanation":"정답 근거: wait는 목적어를 바로 받지 못하는 자동사라 for가 필요하다. wait for + O + to부정사로 “O가 ~하기를 기다리다”를 나타내므로 waiting for다.\n\n보기 비교: approach · enter처럼 전치사를 빼는 동사와 반대다. waiting the rain(X), waiting to the rain(X).\n\n기억 연결: wait → for가 필수(wait for the rain to stop). “전치사 금지” 무리와 짝으로 외운다."},
  {"n":44,"point":"부가의문문(주절 기준)","lesson":"question-form","type":"text","question":"“그는 네가 그 시험에 합격할 거라고 말했지, 그렇지?”\nHe said that you would pass the exam, ___?\n부가의문문 두 단어를 쓰세요.","answers":["didn't he","didnt he","did he not"],"explanation":"정답 근거: 부가의문문은 주절 He said에 맞춘다. 일반동사 과거 긍정문이므로 didn’t he다.\n\n보기 비교: that절의 you would pass에 맞춘 wouldn’t you는 틀리다.\n\n기억 연결: say · think · believe + that절 → 꼬리는 주절(He said → didn’t he)."},
  {"n":45,"point":"remain + p.p.","lesson":"linking","type":"text","question":"“모든 출입문은 밤새 잠긴 채로 있었다.”\nAll the entrance doors remained ___ throughout the night.\nlock을 알맞은 형태로 바꿔 한 단어로 쓰세요.","answers":["locked"],"explanation":"정답 근거: 문은 잠기는 대상이고 remain 뒤 보어는 주어의 상태를 나타내므로 과거분사 locked를 쓴다.\n\n보기 비교: locking은 문이 무엇을 잠그고 있다는 뜻이 되어 맞지 않고, 원형 lock은 보어 자리에 올 수 없다.\n\n기억 연결: remain + p.p.(remain locked · remain seated · remain closed)."},
  {"n":46,"point":"lie/lay","lesson":"lookalike","type":"text","question":"“그 환자는 아직 침대에 누워 있다.”\nThe patient is still ___ in bed.\nlie 또는 lay 중 알맞은 동사를 -ing형 한 단어로 쓰세요.","answers":["lying"],"explanation":"정답 근거: 눕는 동작에는 목적어가 없으므로 자동사 lie를 쓰고, 그 -ing형은 철자가 바뀌어 lying이다.\n\n보기 비교: laying은 타동사 lay(놓다)의 -ing형이라 목적어가 있어야 한다.\n\n기억 연결: lie → lying(눕다) / lay → laying(놓다). 침대에 “누워 있다”는 lying."},
  {"n":47,"point":"found/find","lesson":"lookalike","type":"text","question":"“그 대학은 1946년에 한 무리의 의사들이 설립했다.”\nThe university was ___ in 1946 by a group of doctors.\nfind 또는 found 중 알맞은 동사를 과거분사 한 단어로 쓰세요.","answers":["founded"],"explanation":"정답 근거: “설립하다”는 found-founded-founded이므로 수동태 was founded다.\n\n보기 비교: was found는 find(찾다)의 수동태라 “발견되었다”라는 다른 뜻이 된다.\n\n기억 연결: 대학 · 회사 · 학교 → found-founded. 잃어버린 물건 → find-found."},
  {"n":48,"point":"rise/raise(수동 불가)","lesson":"no-passive","type":"text","question":"“실업률이 석 달 연속 올랐다.”\nUnemployment [has been risen] for three months in a row.\n대괄호 부분을 두 단어로 고쳐 쓰세요.","answers":["has risen"],"explanation":"정답 근거: rise는 목적어가 없는 자동사라 수동태가 없다. 스스로 오른 것이므로 현재완료 능동 has risen으로 고친다.\n\n보기 비교: 누가 올렸다는 뜻이라면 타동사 raise를 써서 has been raised가 되지만, 실업률은 누가 올리는 대상이 아니다.\n\n기억 연결: rise-rose-risen → be risen(X). 수동이 필요하면 raise → be raised."},
  {"n":49,"point":"간접의문문 어순","lesson":"question-form","type":"text","question":"“나는 그녀가 어디에 사는지 모른다.”\nI don't know where ___.\nshe와 live를 알맞은 어순과 형태로 두 단어로 쓰세요.","answers":["she lives"],"explanation":"정답 근거: where절이 know의 목적어로 들어간 간접의문문이므로 의문사 + 주어 + 동사 어순이다. 주어가 she라 lives다.\n\n보기 비교: where does she live처럼 do를 넣어 도치하지 않는다.\n\n기억 연결: know · wonder · tell + where → “주어 + 동사”(where she lives)."},
  {"n":50,"point":"resist/admit/avoid/deny/mind/postpone + -ing","lesson":"gerund-only","type":"text","question":"“그 꼬마는 병원에 끌려가지 않으려고 버텼다.”\nThe little boy resisted ___ to the doctor.\ntake를 사용해 수동 동명사 두 단어로 쓰세요.","answers":["being taken"],"explanation":"정답 근거: resist는 동명사만 목적어로 쓰고, 꼬마는 데려가지는 쪽이므로 수동 동명사 being + p.p.인 being taken이다.\n\n보기 비교: to be taken은 resist 뒤에 올 수 없고, taking은 꼬마가 누군가를 데려간다는 뜻이 된다.\n\n기억 연결: resist → -ing, 당하면 being p.p.(resist being taken · avoid being seen)."},
  {"n":51,"point":"지각동사/keep/have + p.p.","lesson":"object-voice","type":"text","question":"“비행 중에는 안전벨트를 맨 상태로 두세요.”\nKeep your seat belt ___ during the flight.\nfasten을 알맞은 형태로 바꿔 한 단어로 쓰세요.","answers":["fastened"],"explanation":"정답 근거: 안전벨트는 매어지는 대상이므로 keep + 목적어 + 과거분사 fastened다.\n\n보기 비교: fastening은 벨트가 무엇을 매고 있다는 뜻이 되고, 원형 fasten은 keep의 목적격보어로 쓰지 않는다.\n\n기억 연결: keep + O + p.p.(keep it fastened · keep me posted)."},
  {"n":52,"point":"let + O + be p.p.","lesson":"object-voice","type":"text","question":"“이 사진들이 인터넷에 올라가게 두지 마세요.”\nDon't let these photos ___ online.\npost를 사용해 두 단어로 쓰세요.","answers":["be posted"],"explanation":"정답 근거: let 뒤에는 원형이 오고, 사진은 올려지는 대상이므로 원형 자리에 be + p.p.를 넣어 be posted다.\n\n보기 비교: to be posted는 let 뒤에 to가 붙어 틀리고, posted만 쓰면 let의 원형 자리가 비게 된다.\n\n기억 연결: let + O + be p.p.(let them be posted). want · expect였다면 to be posted."},
  {"n":53,"point":"want/expect + O + to be p.p.","lesson":"object-voice","type":"text","question":"“사장은 그 보고서가 정오까지 마무리되기를 원한다.”\nThe boss wants the report to ___ by noon.\nfinish를 사용해 두 단어로 쓰세요.","answers":["be finished"],"explanation":"정답 근거: want + 목적어 + to부정사에서 보고서는 마무리되는 대상이므로 to 뒤에 be + p.p.를 넣어 be finished다.\n\n보기 비교: to finish는 보고서가 스스로 무엇을 끝낸다는 뜻이 되어 맞지 않다.\n\n기억 연결: want · expect + O + to be p.p.(want it to be finished)."},
  {"n":54,"point":"encourage/allow/advise/cause/force/persuade + O + to","lesson":"object-form","type":"text","question":"“선생님은 우리가 매일 영어 일기를 쓰도록 격려하셨다.”\nOur teacher encouraged us ___ an English diary every day.\nkeep을 알맞은 형태로 바꿔 두 단어로 쓰세요.","answers":["to keep"],"explanation":"정답 근거: encourage는 목적어 뒤에 to부정사를 쓰므로 to keep이다.\n\n보기 비교: keeping이나 원형 keep은 encourage의 목적격보어로 쓰지 않는다.\n\n기억 연결: encourage · allow · advise · cause · force · persuade + O + to do."},
  {"n":55,"point":"make/let/have + 원형","lesson":"object-form","type":"text","question":"“매니저는 우리에게 근무 중 유니폼을 입게 했다.”\nThe manager made us ___ uniforms at work.\nwear를 알맞은 형태로 바꿔 한 단어로 쓰세요.","answers":["wear"],"explanation":"정답 근거: 사역동사 make는 목적어가 직접 하는 동작을 원형부정사로 쓰므로 wear 그대로다.\n\n보기 비교: to wear나 wearing은 make의 목적격보어로 쓰지 않는다(수동태 We were made to wear에서만 to가 살아난다).\n\n기억 연결: make · let · have + O + 원형(made us wear)."},
  {"n":56,"point":"keep/prevent/stop A from -ing","lesson":"object-form","type":"text","question":"“부상 때문에 그녀는 결승전에 뛰지 못했다.”\nAn injury prevented her ___ in the final.\nplay를 사용해 두 단어로 쓰세요.","answers":["from playing"],"explanation":"정답 근거: prevent A from -ing로 “A가 ~하지 못하게 하다”를 나타내므로 from playing이다.\n\n보기 비교: to play는 prevent 뒤 형태가 아니다.\n\n기억 연결: prevent · keep · stop + A + from -ing."},
  {"n":57,"point":"accuse A of B","lesson":"prep-pair","type":"text","question":"“그들은 그 운전자를 빨간불에 달린 혐의로 고발했다.”\nThey accused the driver ___ running a red light.\n빠진 한 단어를 쓰세요.","answers":["of"],"explanation":"정답 근거: accuse A of B로 고발 · 비난의 이유를 of로 연결한다.\n\n보기 비교: for는 blame A for B의 짝이고, with는 charge A with B의 짝이다.\n\n기억 연결: accuse → of(accuse A of -ing)."},
  {"n":58,"point":"forget/remember/regret/stop + to vs -ing","lesson":"infinitive-gerund","type":"text","question":"“내일 아침에 약 먹는 거 잊지 마.”\nDon't forget [taking] your medicine tomorrow morning.\n대괄호 부분을 두 단어로 고쳐 쓰세요.","answers":["to take"],"explanation":"정답 근거: 내일 아침에 앞으로 할 일을 잊지 말라는 뜻이므로 forget to take로 고친다.\n\n보기 비교: forget taking은 이미 먹은 일을 잊는다는 뜻이라 tomorrow와 맞지 않다.\n\n기억 연결: forget · remember + tomorrow(앞으로) → to do / + 지난 일 → -ing."},
  {"n":59,"point":"demand/reason/need for","lesson":"finite","type":"text","question":"“새 병원이 필요하다는 데 모두가 동의했다.”\nEveryone agreed on the need ___ a new hospital.\n빠진 한 단어를 쓰세요.","answers":["for"],"explanation":"정답 근거: 명사 need는 무엇이 필요한지를 for로 연결하므로 the need for a new hospital이다.\n\n보기 비교: the need of나 the need to a new hospital로 쓰지 않는다.\n\n기억 연결: 명사 need · demand · reason → for."},
  {"n":60,"point":"It takes (사람) 시간 to do","lesson":"it-takes","type":"text","question":"“우리가 그 책상을 조립하는 데 두 시간이 걸렸다.”\nIt took ___ two hours to put the desk together.\nwe를 알맞은 형태로 바꿔 한 단어로 쓰세요.","answers":["us"],"explanation":"정답 근거: It takes + 사람 + 시간 + to부정사에서 사람은 take의 목적어이므로 목적격 us를 쓴다.\n\n보기 비교: we나 our는 이 자리에 오지 않는다.\n\n기억 연결: It took + us · her · them + 시간 + to do."}
 ];
 // 문제집 Day 2 — PART 02 동사의 형태, 명사, 일치(031~060). 60문제(4지선다 40 · 직접 쓰기 20)이고 한 줄이 곧 문제 하나다.
 // 원서 문장은 쓰지 않고 같은 문법 포인트를 새 문장으로 만든 원고(research/english-days/day2-60.json)를 한 글자도 바꾸지 않고 옮겼다.
 // lesson은 해설 화면에 함께 나오는 규칙 정리(11개)이고, point(30개)는 그 문제가 훈련하는 문법 포인트다. 같은 point는 review-policy.js에서 한 개념이다.
 const DAY2_LESSONS={
  "perfect":{"title":"과거완료와 since + 현재완료","rule":"과거의 한 시점보다 먼저 일어난 일은 had + p.p.(과거완료)로 쓴다. since 뒤에 과거 시점(연도·과거 사건)이 오면 그때부터 지금까지 이어지는 일이므로 주절은 현재완료(have p.p.)로 쓴다. 끝난 과거 시점(when + 과거, yesterday, in 2019)과 현재완료는 함께 쓰지 않는다.","hook":"과거보다 더 과거 → had p.p. / since + 과거 → have p.p.","examples":["The movie had already started when we found our seats.","She has worked here since she graduated in 2020."]},
  "tense-clause":{"title":"시제 일치·부사절의 시제·상태동사","rule":"주절이 과거면 that절의 시제도 과거나 과거완료로 맞춘다(변하지 않는 진리는 현재, 역사적 사실은 과거). 시간·조건을 나타내는 부사절(when·if·once·as soon as·until)에서는 앞으로의 일도 현재시제로 쓰지만, know·wonder의 목적어인 명사절에서는 will을 그대로 쓴다. belong·own·know·contain 같은 상태동사는 진행형으로 쓰지 않는다.","hook":"주절 과거 → that절 과거 / 부사절 → will 빼기 / 상태동사 → -ing 금지","examples":["He told me that he had lost his wallet the day before.","I will call you when I get home."]},
  "modal":{"title":"must have p.p.·cannot be too·used to","rule":"must have p.p.는 과거 일에 대한 강한 추측(~했음에 틀림없다)이고, cannot have p.p.는 “~했을 리 없다”, should have p.p.는 “~했어야 했다”이다. cannot be too + 형용사는 “아무리 ~해도 지나치지 않다”이다. used to do는 “예전에 ~하곤 했다”, be used to -ing는 “~하는 데 익숙하다”, be used to do는 “~하는 데 쓰이다”이며 주어와 문맥이 어느 것인지 정한다.","hook":"과거 추측 → must have p.p. / 익숙함 → be used to -ing / 용도 → be used to 원형","examples":["She must have missed the bus; she is never this late.","You cannot be too careful with your passwords."]},
  "subjunctive":{"title":"당위의 that절 — (should) + 동사원형","rule":"essential·necessary·important 같은 판단 형용사나 insist·demand·suggest·recommend 같은 요구·주장·제안 동사 뒤의 that절이 “~해야 한다”는 당위를 말하면 동사는 (should) + 원형이다. 주어가 3인칭 단수여도 -s를 붙이지 않는다. 다만 insist·suggest가 이미 일어난 사실을 주장·암시하면 당위가 아니므로 시제에 맞춘 직설법을 쓴다.","hook":"“~해야 한다”면 원형 / 사실 주장이면 시제대로","examples":["It is necessary that he be present at the hearing.","She insisted that she had locked the door."]},
  "passive-object":{"title":"목적어나 to부정사가 남는 수동태","rule":"4형식 동사(offer·give·show)의 간접목적어를 주어로 올리면 직접목적어가 동사 뒤에 그대로 남는다(be offered a job). ask·tell·advise + O + to do를 수동태로 바꾸면 be asked to do가 된다. 지각동사 see·hear와 사역동사 make는 능동태에서 원형부정사를 쓰지만 수동태가 되면 to부정사로 바뀐다(be seen to do, be made to do). 지각동사는 be seen -ing도 쓸 수 있다.","hook":"능동의 원형 → 수동에서는 to부정사","examples":["She was offered a place at the university.","The boy was made to clean his room."]},
  "passive-limits":{"title":"수동태를 만들 수 없는 동사·구동사의 수동태","rule":"appear·disappear·happen·occur·arise처럼 목적어를 받지 않는 자동사는 수동태로 쓰지 않는다. look after·laugh at·deal with·take care of 같은 구동사는 한 덩어리의 타동사처럼 수동태가 되며 전치사를 떨어뜨리지 않는다(be laughed at by). concern은 “관련시키다”라는 타동사라 “~와 관련되다”는 be concerned with로 쓴다(be concerned about은 “걱정하다”).","hook":"자동사 → be p.p. 금지 / 구동사 → 전치사까지 통째로","examples":["The problem arose from a simple mistake.","The children were looked after by their aunt."]},
  "agreement-quantity":{"title":"수량 표현과 동사의 수","rule":"the number of + 복수명사는 “~의 수”라서 단수동사, a number of + 복수명사는 “많은 ~”라서 복수동사를 쓴다. percent·half·most·some·the rest·분수 + of + 명사는 of 뒤 명사의 수에 동사를 맞춘다. one of the + 복수명사의 주어는 one이라 단수동사를 쓰고, of 뒤에는 복수명사가 온다.","hook":"the number of → is / a number of → are / 부분 of + 명사 → 명사 기준 / one of → is","examples":["The number of applicants has doubled.","Most of the money was spent on food."]},
  "agreement-subject":{"title":"진짜 주어 찾기 — there 구문과 긴 수식어","rule":"there + be(seem to be·appear to be·remain·exist) 구문에서 동사는 뒤에 오는 진짜 주어에 수를 맞춘다. 주어 뒤에 of 구·전치사구·분사구가 길게 붙어도 동사는 맨 앞의 핵심 명사에 맞추며, 그 주어가 동작을 하는지(능동) 받는지(수동)도 함께 판단한다.","hook":"there 뒤 명사 / of 앞 명사가 주인","examples":["There seem to be two ways to solve it.","Boxes of old books have been stored in the attic."]},
  "pronoun":{"title":"대명사의 수·짝·가목적어","rule":"재귀대명사는 가리키는 주어의 수와 인칭에 맞춘다(birds → themselves). 둘 중 “하나 … 나머지 하나”는 one … the other이고, A is one thing, B is another는 “A와 B는 별개다”라는 뜻이다. make·find·think 뒤에 to부정사나 that절 목적어가 길게 오면 목적어 자리에 가목적어 it을 두고 진짜 목적어를 뒤로 보낸다.","hook":"주어에 수 맞추기 / 별개다 → another / make it + 형용사 + to do","examples":["The kittens washed themselves in the sun.","I found it difficult to sleep on the plane."]},
  "noun":{"title":"셀 수 없는 명사·such a 어순·by the + 신체부위","rule":"information·advice·furniture·equipment·luggage는 셀 수 없는 명사라 -s를 붙이거나 many를 쓰지 않고 a piece of·much·a lot of로 양을 나타낸다. such는 such + a + 형용사 + 명사, so는 so + 형용사 + a + 명사 어순이다. “사람의 신체 일부를 잡다”는 동사 + 사람 + by the + 신체부위로, 소유격 대신 the를 쓴다.","hook":"information에 -s 금지 / such a + 형용사 + 명사 / by the hand","examples":["He gave me two pieces of advice.","The nurse took the boy by the hand."]},
  "inversion-negation":{"title":"부정어 도치와 부분부정","rule":"Hardly·Scarcely·Never·Rarely·Little·Only + 부사(구·절)·Not until ~ 같은 부정·제한 표현이 문장 맨 앞에 오면 조동사와 주어의 어순을 바꾼다(Hardly had S p.p. when ~, Not until ~ did S + 원형). No sooner는 than, Hardly·Scarcely는 when·before와 짝이다. not + always·completely는 “항상(완전히) ~한 것은 아니다”라는 부분부정이고, “결코·전혀 ~않다”라는 전체부정은 never·not at all로 쓴다.","hook":"부정어가 앞으로 → 조동사가 주어 앞으로 / not always = 부분, never = 전체","examples":["Hardly had we left when it started to snow.","Not until the next day did he call me back."]}
 };
 const DAY2=[
  {"n":1,"point":"과거완료(had p.p.) — 과거 시점보다 앞선 일","lesson":"perfect","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["By the time the firefighters arrived, the old barn had already burned down.","Nobody had told me about the schedule change before I checked the website.","When we got to the platform, the last train has already left for Busan.","My aunt has lived in the same small village since she got married."],"correctIndex":2,"explanation":"정답 근거: 우리가 승강장에 도착한(got) 과거 시점보다 기차가 떠난 일이 먼저이므로 과거완료를 써서 had already left로 고친다. 현재완료 has left는 과거 시점(when we got …)과 함께 쓰지 않는다.\n\n보기 비교: ① 소방관이 도착한 과거보다 헛간이 먼저 타 버렸으므로 had burned down이 옳다. ② 웹사이트를 확인한 과거보다 먼저의 일이라 had told가 옳다. ④ since + 과거 사건(she got married) 뒤 주절이 현재완료 has lived라 옳다.\n\n기억 연결: When · By the time + 과거 → 그보다 먼저 끝난 일은 had p.p. “도착했을 때 이미(already) 떠났다” = had already left."},
  {"n":2,"point":"since + 과거 시점 → 현재완료","lesson":"perfect","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["Ever since the new bridge opened, traffic downtown has become much lighter.","The two coastal cities were sister cities since 1998.","I had never tasted durian before I traveled to Malaysia last year.","The folk festival has been held every autumn for more than forty years."],"correctIndex":1,"explanation":"정답 근거: since 1998은 1998년부터 지금까지 이어지는 기간이므로 과거시제 were가 아니라 현재완료 have been으로 고친다.\n\n보기 비교: ① Ever since + 과거(opened) 뒤 주절이 현재완료 has become이라 옳다. ③ 말레이시아에 간 과거보다 먼저의 경험이라 과거완료 had never tasted가 옳다. ④ for more than forty years로 지금까지 이어진 기간이라 현재완료 수동 has been held가 옳다.\n\n기억 연결: since + 연도 · 과거 사건 → 주절은 have p.p. since 1998 + were(X) / have been(O)."},
  {"n":3,"point":"시제 일치(주절 과거 → that절 과거·과거완료)","lesson":"tense-clause","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["Our history teacher explained to us that the Korean War broke out in 1950.","The witness said that she sees the man enter the bank the night before.","He believed that his brother had borrowed the car without asking.","The guide reminded us that the earth goes around the sun once a year."],"correctIndex":1,"explanation":"정답 근거: 주절이 과거(said)이고 목격한 일은 그 전날 밤(the night before)에 이미 끝난 일이므로 현재 sees를 과거완료 had seen(또는 과거 saw)으로 고친다.\n\n보기 비교: ① 역사적 사실은 주절과 상관없이 과거시제로 쓰므로 broke out이 옳다. ③ 믿은(believed) 과거보다 먼저 차를 빌려 간 일이라 had borrowed가 옳다. ④ 변하지 않는 과학적 사실은 주절이 과거여도 현재시제 goes로 쓸 수 있어 옳다.\n\n기억 연결: said · told · believed(과거) + that절 → 과거 · 과거완료. the night before(그 전날 밤)가 보이면 had p.p. 예외: 진리는 현재, 역사는 과거."},
  {"n":4,"point":"시간·조건 부사절은 현재로 미래 표현","lesson":"tense-clause","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["I wonder whether the package will arrive before Friday.","Once you will sign the contract, you cannot change any of the terms.","Nobody knows exactly when the new city library will open to the public.","If it rains on Saturday, the outdoor concert will be postponed."],"correctIndex":1,"explanation":"정답 근거: once(일단 ~하면)가 이끄는 조건 부사절에서는 미래의 일도 현재시제로 쓰므로 will sign을 sign으로 고친다.\n\n보기 비교: ① whether절은 wonder의 목적어인 명사절이라 will arrive가 옳다. ③ when절도 knows의 목적어인 명사절(언제 ~할지)이라 will open이 옳다. ④ if 조건 부사절은 현재 rains, 주절은 미래 will be postponed로 옳다.\n\n기억 연결: once · when · if · as soon as · until이 이끄는 부사절 → will 빼고 현재. 단 know · wonder의 목적어(명사절)면 will 그대로."},
  {"n":5,"point":"상태동사(belong/own/know/contain) 진행형 불가","lesson":"tense-clause","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["The chef is tasting the sauce to check whether it needs more salt.","She is having lunch with two important clients at the moment.","The wooden box on the top shelf contains old letters and photos.","This old castle is belonging to a wealthy family from Scotland."],"correctIndex":3,"explanation":"정답 근거: belong(~에 속하다)은 상태를 나타내는 동사라 진행형으로 쓰지 않으므로 is belonging을 belongs로 고친다.\n\n보기 비교: ① taste가 “맛을 보다”라는 동작이면 진행형 is tasting이 옳다. ② have가 “먹다”라는 동작이면 진행형 is having이 옳다. ③ contain은 상태동사라 현재형 contains가 옳다.\n\n기억 연결: belong · own · know · contain · resemble → -ing 금지. taste · have는 “동작” 뜻일 때만 진행형 가능."},
  {"n":6,"point":"must have p.p.(~했음에 틀림없다)","lesson":"modal","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["The streets are all wet, so it must have rained heavily last night.","You should have told me earlier that you were feeling sick.","He must know the truth yesterday, but he kept quiet about it.","She cannot have forgotten our meeting; she wrote it in her diary."],"correctIndex":2,"explanation":"정답 근거: yesterday라는 과거의 일에 대한 강한 추측이므로 must + 원형이 아니라 must have p.p.를 써서 must have known으로 고친다.\n\n보기 비교: ① 길이 젖은 것을 보고 지난밤의 일을 추측하므로 must have rained가 옳다. ② 과거에 하지 않은 일에 대한 후회라 should have told가 옳다. ④ 과거 일에 대한 강한 부정 추측(~했을 리 없다)이라 cannot have forgotten이 옳다.\n\n기억 연결: yesterday · last night + “~했음에 틀림없다” → must have p.p. must know는 현재에 대한 추측이다."},
  {"n":7,"point":"cannot be too ~(아무리 ~해도 지나치지 않다)","lesson":"modal","type":"choice","question":"다음 중 우리말을 영어로 옳게 옮긴 것은?","choices":["이 길을 건널 때는 아무리 조심해도 지나치지 않다. → You cannot be too careful when you cross this road.","그 가게는 일요일에는 결코 문을 여는 법이 없다. → The corner shop does not always open on Sundays.","그녀가 역에 도착하자마자 비가 세차게 오기 시작했다. → No sooner she had arrived at the station than it began to pour.","그 끔찍한 사고는 어젯밤 자정 무렵에 고속도로에서 일어났다. → The terrible accident was happened on the highway around midnight."],"correctIndex":0,"explanation":"정답 근거: cannot be too + 형용사는 “아무리 ~해도 지나치지 않다”라는 뜻이므로 우리말을 옳게 옮겼다.\n\n보기 비교: ② “결코 ~않는다”는 전체부정이라 not always(항상 ~한 것은 아니다)가 아니라 The corner shop never opens on Sundays로 옮긴다. ③ No sooner가 문장 앞에 오면 도치하므로 No sooner had she arrived로 고친다. ④ happen은 자동사라 수동태가 없으므로 happened로 고친다.\n\n기억 연결: “아무리 ~해도 지나치지 않다” = cannot be too + 형용사(cannot be too careful). can be too careful은 “너무 조심할 수 있다”로 뜻이 반대다."},
  {"n":8,"point":"used to do / be used to -ing / be used to do","lesson":"modal","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["My grandfather used to walk five kilometers to school every day.","After ten long winters in Moscow, she is now used to driving in heavy snow.","This thick rope is used to tie the fishing boats to the dock.","I am used to get up at five because I have worked at a bakery for years."],"correctIndex":3,"explanation":"정답 근거: 빵집에서 오래 일해 새벽 기상에 “익숙하다”는 뜻이므로 be used to 뒤에 동명사를 써서 am used to getting up으로 고친다. 여기서 to는 전치사다.\n\n보기 비교: ① 예전에 매일 걸어 다니던 습관이라 used to walk가 옳다. ② 눈길 운전에 익숙하다는 뜻이라 is used to driving이 옳다. ③ 밧줄은 배를 묶는 데 “쓰인다”는 수동의 뜻이라 is used to tie(to부정사)가 옳다.\n\n기억 연결: 사람 + be used to -ing(익숙하다) / 사물 + be used to 원형(~하는 데 쓰이다) / used to 원형(예전에 ~했다)."},
  {"n":9,"point":"used to do / be used to -ing / be used to do","lesson":"modal","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["Salt was used to keeping meat fresh long before refrigerators existed.","There used to being a small bakery on the corner of our street.","Having grown up on a farm, he is used to waking up before dawn.","We are used to take the subway, so the long commute is no problem."],"correctIndex":2,"explanation":"정답 근거: 농장에서 자라 새벽 기상에 “익숙하다”는 뜻이므로 be used to + 동명사 waking up이 옳다.\n\n보기 비교: ① 소금은 고기를 신선하게 유지하는 데 “쓰였다”는 뜻이라 was used to keep으로 고친다. ② “예전에 ~이 있었다”는 used to be이므로 There used to be로 고친다. ④ 지하철 타는 데 익숙하다는 뜻이라 are used to taking으로 고친다.\n\n기억 연결: “익숙하다” → be used to -ing / “쓰이다” → be used to 원형 / “예전엔 ~였다” → used to 원형. 주어가 사물(salt)이면 대개 “쓰이다”."},
  {"n":10,"point":"It is essential/important that S (should) 원형","lesson":"subjunctive","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["It is essential that each visitor wear a hard hat inside the mine.","Hardly the guests had sat down when the lights suddenly went out.","The number of tourists visiting the island every summer have doubled.","The missing painting was disappeared from the gallery last week."],"correctIndex":0,"explanation":"정답 근거: essential 같은 이성적 판단 형용사 뒤 that절이 “~해야 한다”는 당위를 말하므로 (should) wear가 되고, 주어가 3인칭 단수 each visitor여도 원형 wear가 옳다.\n\n보기 비교: ② Hardly가 문장 앞에 오면 도치하므로 Hardly had the guests sat down으로 고친다. ③ 주어가 the number(수)라 단수이므로 has doubled로 고친다. ④ disappear는 자동사라 수동태가 없으므로 disappeared로 고친다.\n\n기억 연결: It is essential · necessary · important that + S + (should) 원형. each visitor wears(X) → wear(O)."},
  {"n":11,"point":"insist/demand/suggest that — 당위면 원형, 사실이면 시제대로","lesson":"subjunctive","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["The residents demanded that the factory stop dumping waste into the river.","The boy insisted that he not break the vase, but nobody believed him.","It is important that the medicine be kept out of children’s reach.","The coach suggested that the whole team practice their passes more often."],"correctIndex":1,"explanation":"정답 근거: insist 뒤 that절이 “~해야 한다”는 요구가 아니라 “꽃병을 깨지 않았다”는 과거 사실의 주장이다(아무도 그 말을 믿지 않았다). 사실을 주장할 때는 원형을 쓰지 않으므로 not break를 직설법 과거 did not break로 고친다.\n\n보기 비교: ① 요구 동사 demand 뒤 당위의 that절이라 원형 stop이 옳다. ③ important 뒤 당위의 that절이라 be kept가 옳다. ④ 제안 동사 suggest 뒤 당위의 that절이라 원형 practice가 옳다.\n\n기억 연결: insist · suggest + that → “~해야 한다”면 원형, “~였다(사실)”면 시제대로. nobody believed him(주장을 믿지 않음 → 사실 주장)이 단서."},
  {"n":12,"point":"4형식 수동(be offered + 직접목적어)","lesson":"passive-object","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["The students were explained the new rules by the principal.","A strange noise was heard come from the old basement late at night.","Every winner were handed a certificate and a medal by the mayor.","All new employees are offered a free health checkup every spring."],"correctIndex":3,"explanation":"정답 근거: offer는 4형식 동사라 간접목적어(employees)를 주어로 올린 수동태에서도 직접목적어 a free health checkup이 동사 뒤에 그대로 남으므로 옳다.\n\n보기 비교: ① explain은 4형식을 쓰지 않으므로 The new rules were explained to the students로 고친다. ② 지각동사 hear의 수동태 뒤에는 to부정사나 현재분사가 오므로 was heard to come(또는 coming)으로 고친다. ③ Every + 단수명사는 단수동사를 쓰므로 Every winner was handed로 고친다.\n\n기억 연결: offer · give · show · send + 사람 + 물건 → 사람 + be offered + 물건. explain · suggest는 사람을 주어로 한 수동태를 만들지 않는다."},
  {"n":13,"point":"ask/tell/advise O to do의 수동(be asked to do)","lesson":"passive-object","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["Visitors are asked turning off their phones during the performance.","The workers were told to wear safety goggles at all times.","We were advised to book our tickets at least a week in advance.","The students were made to rewrite their history essays over the weekend."],"correctIndex":0,"explanation":"정답 근거: ask + 목적어 + to do를 수동태로 바꾸면 be asked to do이므로 turning off를 to turn off로 고친다.\n\n보기 비교: ② tell O to do의 수동 be told to wear라 옳다. ③ advise O to do의 수동 be advised to book이라 옳다. ④ 사역동사 make의 수동태 뒤에는 to부정사를 쓰므로 were made to rewrite가 옳다.\n\n기억 연결: be asked · told · advised · allowed + to do. 수동이 되어도 to부정사는 그대로 남는다."},
  {"n":14,"point":"지각·사역동사 수동태 뒤 to부정사(be seen to do)","lesson":"passive-object","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["The children were made to apologize to their elderly next-door neighbor.","The old man was heard muttering something about the weather.","The volunteers were asked to collect trash along the beach.","The suspect was seen enter the building shortly after midnight."],"correctIndex":3,"explanation":"정답 근거: 지각동사 see는 능동태에서 원형부정사를 쓰지만(saw him enter) 수동태가 되면 to부정사로 바뀌므로 was seen to enter(또는 entering)로 고친다.\n\n보기 비교: ① 사역동사 make의 수동태 뒤 to부정사 were made to apologize라 옳다. ② hear의 수동태 뒤 현재분사 was heard muttering이라 옳다. ③ ask O to do의 수동 were asked to collect라 옳다.\n\n기억 연결: saw him enter(능동) → he was seen to enter(수동). 수동태 지각 · 사역동사 뒤 원형(X), to부정사(O)."},
  {"n":15,"point":"지각·사역동사 수동태 뒤 to부정사(be seen to do)","lesson":"passive-object","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["The new sales manager was seen leave the office early every Friday.","The prisoners were made work in the fields from dawn to dusk.","The two leaders were seen to shake hands before the talks began.","The sick puppy was taken care by a kind neighbor for a week."],"correctIndex":2,"explanation":"정답 근거: 지각동사 see의 수동태 뒤에 to부정사 to shake를 썼으므로 옳다.\n\n보기 비교: ① 지각동사의 수동태 뒤에는 원형을 쓰지 않으므로 was seen to leave(또는 leaving)로 고친다. ② 사역동사 make의 수동태도 were made to work로 고친다. ④ take care of는 전치사까지 한 덩어리라 was taken care of by로 고친다.\n\n기억 연결: be seen · heard · made + to do. 능동의 원형이 수동에서는 to부정사로 바뀐다."},
  {"n":16,"point":"자동사 수동 불가(occur/happen/appear/disappear)","lesson":"passive-limits","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["A serious accident was occurred on the highway early this morning.","The famous singer appeared on the stage in a bright red dress.","Dinosaurs disappeared from the earth millions of years ago.","The monthly meeting was postponed because the chairman suddenly got sick."],"correctIndex":0,"explanation":"정답 근거: occur(일어나다)는 목적어를 받지 않는 자동사라 수동태로 쓰지 않으므로 was occurred를 occurred로 고친다.\n\n보기 비교: ② appear도 자동사라 능동 appeared가 옳다. ③ disappear도 자동사라 능동 disappeared가 옳다. ④ postpone은 타동사라 회의가 “연기되었다”는 수동 was postponed가 옳다.\n\n기억 연결: occur · happen · appear · disappear · arise → be p.p.(X). “일어났다 · 나타났다”는 과거형 하나로."},
  {"n":17,"point":"자동사 수동 불가(occur/happen/appear/disappear)","lesson":"passive-limits","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["What was happened to your car in the parking lot last night?","Two new stores have been opened on Main Street this year.","The rare bird has been disappeared from this valley since 2010.","The kids were made clean up the classroom after lunch."],"correctIndex":1,"explanation":"정답 근거: open은 “(가게를) 열다”라는 타동사로도 쓰이므로 가게가 “열린” 수동 have been opened가 옳다.\n\n보기 비교: ① happen은 자동사라 수동태가 없으므로 What happened to로 고친다. ③ disappear도 자동사라 has disappeared로 고친다. ④ 사역동사 make의 수동태 뒤에는 to부정사를 쓰므로 were made to clean up으로 고친다.\n\n기억 연결: happen · disappear(자동사만) → 수동 금지 / open · close(타동사로도 씀) → 수동 가능. 목적어를 받을 수 있는 동사인지 먼저 본다."},
  {"n":18,"point":"구동사 수동태(be laughed at by)","lesson":"passive-limits","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["The broken fence was finally taken care of by the landlord.","The weekly meeting was put off until the manager returned from Tokyo.","The nervous speaker was laughed by some people in the audience.","Their complaints were dealt with quickly by the hotel staff."],"correctIndex":2,"explanation":"정답 근거: laugh at(~을 비웃다)은 전치사까지 한 덩어리의 타동사라 수동태에서도 at을 남겨 was laughed at by로 고친다.\n\n보기 비교: ① take care of의 수동 was taken care of by라 옳다. ② put off(연기하다)의 수동 was put off라 옳다. ④ deal with(처리하다)의 수동 were dealt with라 옳다.\n\n기억 연결: laugh at · look after · take care of · deal with → 수동에서도 전치사 그대로(be laughed at by)."},
  {"n":19,"point":"be concerned with(~와 관련되다)","lesson":"passive-limits","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["This chapter is concerned with the causes of the First World War.","Many parents are concerned about the rising cost of school uniforms.","The novel deals with one family’s struggle to survive the war.","Police believe that the mayor concerned with the bribery scandal."],"correctIndex":3,"explanation":"정답 근거: concern은 “관련시키다”라는 타동사라 “~와 관련되어 있다”는 be concerned with로 쓴다. be동사가 빠졌으므로 was concerned with로 고친다.\n\n보기 비교: ① 이 장이 전쟁의 원인과 “관련되어 있다(다룬다)”는 뜻이라 is concerned with가 옳다. ② “걱정하다”는 be concerned about이라 옳다. ③ deal with(다루다)는 능동으로 쓰는 구동사라 deals with가 옳다.\n\n기억 연결: be concerned with(관련되다) / be concerned about(걱정하다). concerned with 앞에 be동사가 빠지면 틀린다."},
  {"n":20,"point":"the number of + 단수동사 / a number of + 복수동사","lesson":"agreement-quantity","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["A number of volunteers have signed up for the beach cleanup.","The number of people living alone are growing in big cities.","A large number of dead fish were found near the chemical plant.","The number of traffic accidents on this road has fallen since 2020."],"correctIndex":1,"explanation":"정답 근거: The number of + 복수명사는 “~의 수”라 주어가 number(단수)이므로 are를 is로 고친다. living alone은 people을 꾸미는 수식어일 뿐이다.\n\n보기 비교: ① A number of + 복수명사는 “많은 ~”라 복수동사 have signed가 옳다. ③ A large number of도 “많은”이라 복수동사 were가 옳다. ④ the number of라 단수동사 has fallen이 옳고, since 2020과 현재완료도 맞다.\n\n기억 연결: The number of → is(수가 하나) / A number of → are(많은 ~들). 관사 the · a가 동사를 정한다."},
  {"n":21,"point":"the number of + 단수동사 / a number of + 복수동사","lesson":"agreement-quantity","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["The number of students who take the school bus has increased.","A number of complaints about the noise has been reported.","The number of hospital beds in the region are far from enough.","There seem to be a problem with the printer on the second floor."],"correctIndex":0,"explanation":"정답 근거: 주어가 The number(~의 수)라 단수동사 has increased가 옳다. who take는 복수명사 students에 맞춘 관계절의 동사라 take가 맞다.\n\n보기 비교: ② A number of complaints는 “많은 불만”이라 복수동사 have been reported로 고친다. ③ The number of hospital beds의 주어는 number라 is로 고친다. ④ there 구문은 뒤의 주어 a problem에 맞추므로 There seems to be로 고친다.\n\n기억 연결: The number of ~ → 단수(has), A number of ~ → 복수(have). 수식어(who take · in the region)는 건너뛰고 주어를 찾는다."},
  {"n":22,"point":"부분 표현(percent/half/most of) + 명사에 수일치","lesson":"agreement-quantity","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["About 70 percent of the earth’s surface is covered with water.","Most of the furniture in this house was made by my grandfather.","Half of the apples in the basket was already rotten.","Two-thirds of the voters support the new tax plan."],"correctIndex":2,"explanation":"정답 근거: Half of 뒤의 명사 the apples가 복수이므로 동사도 복수 were로 고친다.\n\n보기 비교: ① 70 percent of the earth's surface는 surface(단수)에 맞춰 is가 옳다. ② Most of the furniture는 셀 수 없는 명사라 단수 was가 옳다. ④ Two-thirds of the voters는 복수라 support가 옳다.\n\n기억 연결: percent · half · most · 분수 + of + 명사 → of 뒤 명사가 동사를 정한다(the apples → were)."},
  {"n":23,"point":"부분 표현(percent/half/most of) + 명사에 수일치","lesson":"agreement-quantity","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["Some of the milk in the fridge have already gone sour.","Thirty percent of the annual city budget are spent on staff salaries.","Most of the passengers on the delayed flight were exhausted.","One of my best friends live in a small town in Canada."],"correctIndex":2,"explanation":"정답 근거: Most of 뒤의 명사 the passengers가 복수이므로 복수동사 were가 옳다.\n\n보기 비교: ① Some of the milk는 셀 수 없는 명사라 단수 has gone으로 고친다. ② Thirty percent of the annual city budget은 budget(단수)에 맞춰 is spent로 고친다. ④ One of + 복수명사의 주어는 one이라 lives로 고친다.\n\n기억 연결: 부분 표현 of + 명사 → 명사 기준(milk → has, passengers → were). One of는 늘 단수."},
  {"n":24,"point":"one of the + 복수명사 + 단수동사","lesson":"agreement-quantity","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["One of the main reasons for the long delay was the heavy snow.","One of the paintings in the main hall were stolen last night.","Each of the guest rooms has its own bathroom and balcony.","Neither of the two answers seems quite right to me."],"correctIndex":1,"explanation":"정답 근거: 주어는 One이고 of the paintings in the main hall은 수식어라 단수동사 was stolen으로 고친다.\n\n보기 비교: ① One of the main reasons의 주어 one에 맞춰 was가 옳다. ③ Each of + 복수명사는 단수동사 has가 옳다. ④ Neither of the two answers는 단수동사 seems로 쓸 수 있어 옳다.\n\n기억 연결: One · Each · Neither of + 복수명사 → 단수동사. 가까운 복수명사(paintings)에 속지 않는다."},
  {"n":25,"point":"one of the + 복수명사 + 단수동사","lesson":"agreement-quantity","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["One of the players on our soccer team come from Brazil.","One of the most popular dishes in Korea is bibimbap.","One of my cousin works as a nurse at a hospital in Seoul.","All the luggages were loaded onto the bus before breakfast."],"correctIndex":1,"explanation":"정답 근거: 주어 One에 맞춰 단수동사 is를 썼고, one of the most popular 뒤에 복수명사 dishes가 와서 옳다.\n\n보기 비교: ① 주어가 One이라 comes로 고친다. ③ One of 뒤에는 복수명사가 오므로 One of my cousins로 고친다. ④ luggage는 셀 수 없는 명사라 All the luggage was loaded로 고친다.\n\n기억 연결: One of the + 복수명사 + 단수동사. cousin(X) → cousins(O), come(X) → comes(O)."},
  {"n":26,"point":"there 구문(there seem(s) to be) 수일치","lesson":"agreement-subject","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["There seem to be a leak somewhere in the heating system.","There are fewer cars on the road during the holidays.","There have been three small earthquakes in the region this month.","There is little hope of finding more survivors now."],"correctIndex":0,"explanation":"정답 근거: there 구문의 동사는 뒤에 오는 진짜 주어에 수를 맞추는데, 주어 a leak이 단수이므로 seem을 seems로 고친다.\n\n보기 비교: ② 주어 fewer cars가 복수라 are가 옳다. ③ 주어 three small earthquakes가 복수라 have been이 옳다. ④ 주어 little hope가 셀 수 없는 명사라 is가 옳다.\n\n기억 연결: There seem(s) to be + 명사 → be 뒤 명사가 주인(a leak → seems). appear to be · remain · exist도 같다."},
  {"n":27,"point":"there 구문(there seem(s) to be) 수일치","lesson":"agreement-subject","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["There appear to be a crack in the kitchen window.","Hardly I had closed my eyes when the phone rang loudly.","There remain several questions that nobody can answer.","There were a strong wind blowing from the north all day."],"correctIndex":2,"explanation":"정답 근거: there 구문에서 remain의 주어는 뒤의 several questions(복수)라 remain이 옳다.\n\n보기 비교: ① 주어 a crack이 단수라 There appears to be로 고친다. ② Hardly가 문장 앞에 오면 도치하므로 Hardly had I closed로 고친다. ④ 주어 a strong wind가 단수라 There was로 고친다.\n\n기억 연결: There + remain · exist · seem to be + 주어 → 뒤의 주어 수에 맞춘다. several questions → remain."},
  {"n":28,"point":"긴 수식어 뒤 주어의 수와 태(have been p.p.)","lesson":"agreement-subject","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["The results of the annual customer survey were announced at the staff meeting.","The keys to the storage room have been lost again.","The quality of the old recordings has improved a lot.","High concentrations of lead in the drinking water was detected last spring."],"correctIndex":3,"explanation":"정답 근거: 주어의 핵심은 concentrations(복수)이고 of lead in the drinking water는 수식어라 was detected를 were detected로 고친다.\n\n보기 비교: ① 주어 results가 복수라 were announced가 옳다. ② 주어 keys가 복수라 have been lost가 옳다. ③ 주어 quality가 단수라 has improved가 옳다.\n\n기억 연결: 긴 주어는 of 앞 명사가 주인(concentrations → were). 뒤의 water · room · recordings에 맞추지 않는다."},
  {"n":29,"point":"긴 수식어 뒤 주어의 수와 태(have been p.p.)","lesson":"agreement-subject","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["Traces of an ancient farming village have discovered under the parking lot.","The members of the new committee has been chosen by vote.","Several copies of the missing report have been found in the basement.","The number of visitors to the museum have risen this year."],"correctIndex":2,"explanation":"정답 근거: 주어 copies(복수)에 맞춰 have를 썼고, 보고서 사본은 “발견된” 것이라 수동 have been found가 옳다.\n\n보기 비교: ① 흔적은 “발견된” 것이라 수동 have been discovered로 고친다. ② 주어 members가 복수라 have been chosen으로 고친다. ④ 주어 The number가 단수라 has risen으로 고친다.\n\n기억 연결: 긴 주어는 두 번 확인한다 — ① 수(copies → have) ② 태(발견“된” → been found)."},
  {"n":30,"point":"재귀대명사 수일치(themselves/itself)","lesson":"pronoun","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["The young birds must soon learn to feed itself.","She taught herself to play the guitar during the summer.","We really enjoyed ourselves at the festival despite the rain.","The machine turns itself off after ten minutes without use."],"correctIndex":0,"explanation":"정답 근거: 재귀대명사는 가리키는 주어에 수를 맞추는데 feed의 주체는 복수 the young birds이므로 itself를 themselves로 고친다.\n\n보기 비교: ② 주어 She에 맞춰 herself가 옳다. ③ 주어 We에 맞춰 ourselves가 옳다. ④ 주어 The machine(단수 사물)에 맞춰 itself가 옳다.\n\n기억 연결: birds · animals · people(복수) → themselves / machine · company(단수) → itself."},
  {"n":31,"point":"one thing … another / one … the other","lesson":"pronoun","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["I have two brothers; one is a nurse, and the other is a pilot.","Some people love hot summers, while others prefer cold winters.","This shirt is too small for me. Could you show me another?","Making a promise is one thing, and keeping it is the other."],"correctIndex":3,"explanation":"정답 근거: “A와 B는 별개다”는 A is one thing, and B is another로 쓴다. 정해진 둘 중 나머지를 가리키는 the other가 아니므로 another로 고친다.\n\n보기 비교: ① 형제가 둘이라 하나는 one, 나머지 하나는 the other가 옳다. ② 막연한 일부 사람은 some, 다른 일부는 others가 옳다. ③ 여러 셔츠 중 “다른 하나”라 another가 옳다.\n\n기억 연결: A is one thing, B is another(별개다). 둘 중 나머지 → the other / 막연한 다른 하나 → another."},
  {"n":32,"point":"가목적어 it(make it + 형용사 + to do)","lesson":"pronoun","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["The loud music made difficult for us to hear each other.","I found it hard to believe his story about the lost wallet.","The new app makes it easy to split the bill with friends.","She thought it strange that nobody answered the door."],"correctIndex":0,"explanation":"정답 근거: make + 목적어 + 형용사에서 진짜 목적어 for us to hear each other가 길어 뒤로 보내면, 목적어 자리에 가목적어 it을 두어야 하므로 made it difficult로 고친다.\n\n보기 비교: ② found it hard to believe로 가목적어 it이 있어 옳다. ③ makes it easy to split도 옳다. ④ thought it strange that ~으로 that절을 진목적어로 받은 가목적어 it이라 옳다.\n\n기억 연결: make · find · think + it + 형용사 + to do · that절. 가목적어 it이 빠지면 틀린다."},
  {"n":33,"point":"불가산명사(information/advice/furniture) 복수 불가","lesson":"noun","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["The hotel clerk gave us many useful advices about the city.","We need to buy some new furnitures for the waiting room.","She gave me a good piece of advice about saving money.","The lab has bought several new equipments this year."],"correctIndex":2,"explanation":"정답 근거: advice는 셀 수 없는 명사라 하나를 셀 때 a piece of advice로 쓰므로 옳다.\n\n보기 비교: ① advice는 복수형이 없으므로 a lot of useful advice로 고친다. ② furniture도 셀 수 없어 some new furniture로 고친다. ④ equipment도 셀 수 없어 some new equipment(또는 several new pieces of equipment)로 고친다.\n\n기억 연결: information · advice · furniture · equipment · luggage → -s(X), many(X), a piece of(O)."},
  {"n":34,"point":"such a + 형용사 + 명사 어순","lesson":"noun","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["He is so kind a person that everyone in town likes him.","I have never seen such a large crowd at a concert before.","The test was so difficult that half the class failed it.","It was a such beautiful day that we went on a picnic."],"correctIndex":3,"explanation":"정답 근거: such는 such + a + 형용사 + 명사 어순이므로 a such beautiful day를 such a beautiful day로 고친다.\n\n보기 비교: ① so는 so + 형용사 + a + 명사 어순이라 so kind a person이 옳다. ② such a large crowd로 어순이 옳다. ③ so + 형용사 + that 구문이라 옳다.\n\n기억 연결: such a + 형용사 + 명사 / so + 형용사 + a + 명사. a such(X), such a(O)."},
  {"n":35,"point":"동사 + 사람 + by the + 신체부위","lesson":"noun","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["The officer caught the pickpocket by the wrist.","Scarcely the plane had landed when the passengers stood up.","Everyone in my class is knowing the answer already.","My grandmother used to living on a small island."],"correctIndex":0,"explanation":"정답 근거: “사람의 신체 일부를 잡다”는 동사 + 사람 + by the + 신체부위로 쓰므로 caught the pickpocket by the wrist가 옳다.\n\n보기 비교: ② Scarcely가 문장 앞에 오면 도치하므로 Scarcely had the plane landed로 고친다. ③ know는 상태동사라 진행형이 없으므로 knows로 고친다. ④ “예전에 ~에 살았다”는 used to live로 고친다.\n\n기억 연결: catch · seize · grab + 사람 + by the + wrist · arm · hand. 소유격(his wrist)이 아니라 the wrist."},
  {"n":36,"point":"부정부사(Hardly/Never/Rarely) 문두 도치","lesson":"inversion-negation","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["Never have I seen such a beautiful sunset over the sea.","Scarcely had the concert begun when the power went out.","Little did he know that his friends were secretly planning a surprise party.","Hardly the teacher had left the room when the kids started shouting."],"correctIndex":3,"explanation":"정답 근거: 부정부사 Hardly가 문장 맨 앞에 오면 조동사와 주어의 어순을 바꾸므로 Hardly had the teacher left로 고친다.\n\n보기 비교: ① Never가 앞에 와서 have I seen으로 도치해 옳다. ② Scarcely had the concert begun when ~으로 도치와 짝(when)이 옳다. ③ Little이 앞에 와서 did he know로 도치해 옳다.\n\n기억 연결: Hardly · Scarcely · Never · Little + 조동사 + 주어. Hardly had S p.p. when ~ = “~하자마자 …했다”."},
  {"n":37,"point":"부정부사(Hardly/Never/Rarely) 문두 도치","lesson":"inversion-negation","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["Rarely I have eaten such fresh seafood in a small seaside restaurant.","No sooner had we sat down than the waiter brought the menu.","Never I will forget the kindness of those strangers.","Only after the storm passed the villagers went outside."],"correctIndex":1,"explanation":"정답 근거: No sooner가 앞에 와서 had we sat down으로 도치했고, No sooner의 짝 than을 써서 옳다.\n\n보기 비교: ① Rarely가 앞에 오면 have I eaten으로 도치한다. ③ Never가 앞에 오면 will I forget으로 도치한다. ④ Only after + 절이 앞에 오면 주절을 did the villagers go로 도치한다.\n\n기억 연결: No sooner had S p.p. than ~ / Hardly · Scarcely had S p.p. when · before ~. 부정어가 앞이면 조동사가 먼저."},
  {"n":38,"point":"Not until ~ 도치(did + S + 원형)","lesson":"inversion-negation","type":"choice","question":"다음 중 어법상 옳지 않은 것은?","choices":["Not until the lights came on did we notice the broken window.","It was not until midnight that the rescue team reached the boat.","Not until he retired he began to paint seriously.","Only then did I realize how much she had helped me."],"correctIndex":2,"explanation":"정답 근거: Not until ~이 문장 앞에 오면 주절을 도치하므로 he began을 did he begin으로 고친다.\n\n보기 비교: ① Not until 뒤 주절이 did we notice로 도치해 옳다. ② It was not until ~ that 강조 구문은 that 뒤를 평서문 어순으로 쓰므로 옳다. ④ Only then이 앞에 와서 did I realize로 도치해 옳다.\n\n기억 연결: Not until ~ + did + 주어 + 원형 = It was not until ~ that + 주어 + 동사. 두 형태의 어순을 구별한다."},
  {"n":39,"point":"부분부정(not always) vs 전체부정(never)","lesson":"inversion-negation","type":"choice","question":"다음 중 우리말을 영어로 옳게 옮긴 것은?","choices":["그는 결코 아침을 거르지 않는다. → He does not always skip breakfast.","부자들이 항상 행복한 것은 아니다. → The rich are not always happy.","나는 그의 말을 전혀 믿지 않는다. → I do not completely believe what he says.","그가 떠난 뒤에야 나는 진실을 알았다. → Not until he left I learned the truth."],"correctIndex":1,"explanation":"정답 근거: not always는 “항상 ~한 것은 아니다”라는 부분부정이므로 우리말을 옳게 옮겼다.\n\n보기 비교: ① “결코 ~않는다”는 전체부정이라 He never skips breakfast로 옮긴다. ③ “전혀 믿지 않는다”는 전체부정이라 I do not believe what he says at all로 옮긴다(not completely는 “완전히 믿지는 않는다”는 부분부정). ④ Not until이 앞에 오면 도치하므로 Not until he left did I learn the truth로 고친다.\n\n기억 연결: not + always · completely · all = 부분부정(“다 ~한 건 아니다”) / never · not at all = 전체부정(“결코 · 전혀”)."},
  {"n":40,"point":"insist/demand/suggest that — 당위면 원형, 사실이면 시제대로","lesson":"subjunctive","type":"choice","question":"다음 중 어법상 옳은 것은?","choices":["Once the new law will take effect next year, smoking in parks will be banned.","She is owning a small café near the train station.","He must forget our appointment last Monday.","The lawyer recommended that her client remain silent during questioning."],"correctIndex":3,"explanation":"정답 근거: recommend 뒤 that절이 “~해야 한다”는 권고라 (should) + 원형이 되므로, 3인칭 단수 her client 뒤에도 원형 remain이 옳다.\n\n보기 비교: ① once 조건 부사절에서는 미래도 현재로 쓰므로 takes effect로 고친다. ② own은 상태동사라 진행형이 없으므로 owns로 고친다. ③ 지난 월요일의 일에 대한 추측이라 must have forgotten으로 고친다.\n\n기억 연결: recommend · suggest · demand · insist(당위) + that + S + (should) 원형. her client remains(X) → remain(O)."},
  {"n":41,"point":"과거완료(had p.p.) — 과거 시점보다 앞선 일","lesson":"perfect","type":"text","question":"“내가 공항에 도착했을 때 비행기는 이미 이륙한 뒤였다.”\nWhen I arrived at the airport, the plane ___ already taken off.\n빠진 한 단어를 쓰세요.","answers":["had"],"explanation":"정답 근거: 공항에 도착한(arrived) 과거 시점보다 비행기가 이륙한 일이 먼저이므로 과거완료 had taken off를 만든다.\n\n보기 비교: has는 현재완료라 과거 시점 when I arrived와 함께 쓰지 않는다. was는 taken off와 수동이 되어 뜻이 맞지 않다.\n\n기억 연결: When + 과거, … already → had p.p. “도착했을 때 이미 ~한 뒤였다”."},
  {"n":42,"point":"시제 일치(주절 과거 → that절 과거·과거완료)","lesson":"tense-clause","type":"text","question":"“그녀는 그 전날 밤 열쇠를 잃어버렸다고 말했다.”\nShe said that she [loses] her keys the night before.\n대괄호 부분을 알맞은 형태로 고쳐 쓰세요.","answers":["had lost","lost"],"explanation":"정답 근거: 주절이 과거(said)이고 열쇠를 잃어버린 일은 그 전날 밤에 끝났으므로 과거완료 had lost로 고친다. 앞뒤 순서가 분명해 과거 lost도 쓸 수 있다.\n\n보기 비교: 현재 loses나 현재완료 has lost는 주절의 과거 said · the night before와 맞지 않다.\n\n기억 연결: said(과거) + the night before → had p.p.(시제 일치)."},
  {"n":43,"point":"시간·조건 부사절은 현재로 미래 표현","lesson":"tense-clause","type":"text","question":"“역에 도착하면 나한테 문자 보내.”\nText me when you [will get] to the station.\n대괄호 부분을 한 단어로 고쳐 쓰세요.","answers":["get"],"explanation":"정답 근거: when이 이끄는 시간 부사절이라 앞으로의 일도 현재시제로 쓰므로 will get을 get으로 고친다.\n\n보기 비교: 주어가 you라 gets가 아니라 get이다. will get은 명사절(언제 도착할지 모른다)일 때만 쓴다.\n\n기억 연결: when · if · once · as soon as + 부사절 → will 빼고 현재."},
  {"n":44,"point":"must have p.p.(~했음에 틀림없다)","lesson":"modal","type":"text","question":"“길이 젖어 있는 걸 보니 밤사이 비가 왔음에 틀림없다.”\nThe road is wet. It ___ rained during the night.\n빠진 두 단어를 쓰세요.","answers":["must have","must've","mustve"],"explanation":"정답 근거: 지난밤의 일에 대한 강한 추측(~했음에 틀림없다)이므로 must have + p.p.를 써서 must have rained로 만든다.\n\n보기 비교: should have rained는 “왔어야 했다”, cannot have rained는 “왔을 리 없다”라 뜻이 다르다.\n\n기억 연결: 과거 일 + “틀림없다” → must have p.p."},
  {"n":45,"point":"used to do / be used to -ing / be used to do","lesson":"modal","type":"text","question":"“그는 매운 음식을 먹는 데 익숙하다.”\nHe is used to [eat] spicy food.\n대괄호 부분을 한 단어로 고쳐 쓰세요.","answers":["eating"],"explanation":"정답 근거: “~하는 데 익숙하다”는 be used to + 동명사이고 to는 전치사이므로 eat을 eating으로 고친다.\n\n보기 비교: 원형 eat을 쓰면 be used to do(~하는 데 쓰이다)가 되어 사람 주어와 뜻이 맞지 않다.\n\n기억 연결: 익숙하다 = be used to -ing / 쓰이다 = be used to 원형 / 예전엔 ~했다 = used to 원형."},
  {"n":46,"point":"It is essential/important that S (should) 원형","lesson":"subjunctive","type":"text","question":"“모든 지원자가 서류를 기한 안에 제출하는 것이 필수적이다.”\nIt is essential that every applicant ___ the documents on time.\nsubmit을 알맞은 형태로 한 단어 또는 두 단어로 쓰세요.","answers":["submit","should submit"],"explanation":"정답 근거: essential 뒤의 that절이 “~해야 한다”는 당위를 말하므로 (should) + 원형을 써서 submit 또는 should submit으로 쓴다.\n\n보기 비교: 주어가 3인칭 단수 every applicant라도 시험 어법에서는 submits로 쓰지 않는다. submitted · will submit도 쓰지 않는다.\n\n기억 연결: It is essential · necessary · important that + S + (should) 원형."},
  {"n":47,"point":"ask/tell/advise O to do의 수동(be asked to do)","lesson":"passive-object","type":"text","question":"“손님들은 현관에서 신발을 벗어 달라는 요청을 받았다.”\nThe guests were asked [taking] off their shoes at the door.\n대괄호 부분을 두 단어로 고쳐 쓰세요.","answers":["to take"],"explanation":"정답 근거: ask + 목적어 + to do의 수동태는 be asked to do이므로 taking을 to take로 고친다.\n\n보기 비교: 원형 take나 동명사 taking은 be asked 뒤에 오지 않는다.\n\n기억 연결: be asked · told · advised + to do."},
  {"n":48,"point":"지각·사역동사 수동태 뒤 to부정사(be seen to do)","lesson":"passive-object","type":"text","question":"“그 소년이 담을 넘어가는 것이 목격되었다.”\nThe boy was seen [climb] over the wall.\n대괄호 부분을 알맞은 형태로 고쳐 쓰세요.","answers":["to climb","climbing"],"explanation":"정답 근거: 지각동사 see의 수동태 뒤에는 원형을 쓰지 않고 to부정사로 바꾸므로 to climb으로 고친다. 동작이 진행 중이던 모습을 말하는 현재분사 climbing도 쓸 수 있다.\n\n보기 비교: 능동태라면 saw the boy climb처럼 원형을 쓰지만 수동태 was seen 뒤에서는 원형 climb을 쓰지 않는다.\n\n기억 연결: saw him climb → he was seen to climb(또는 climbing)."},
  {"n":49,"point":"자동사 수동 불가(occur/happen/appear/disappear)","lesson":"passive-limits","type":"text","question":"“그 작은 마을에서 이상한 일이 일어났다.”\nA strange thing [was happened] in the small village.\n대괄호 부분을 한 단어로 고쳐 쓰세요.","answers":["happened","occurred"],"explanation":"정답 근거: happen은 목적어를 받지 않는 자동사라 수동태로 쓰지 않으므로 was happened를 happened로 고친다. 같은 뜻의 자동사 occurred도 된다.\n\n보기 비교: was happening은 두 단어이고 “일어나고 있었다”라 뜻이 다르다.\n\n기억 연결: happen · occur · appear · disappear → be p.p.(X)."},
  {"n":50,"point":"구동사 수동태(be laughed at by)","lesson":"passive-limits","type":"text","question":"“내가 집을 비운 동안 우리 고양이는 이웃이 돌봐 주었다.”\nWhile I was away, my cat was looked ___ by a neighbor.\n빠진 한 단어를 쓰세요.","answers":["after"],"explanation":"정답 근거: look after(돌보다)는 전치사까지 한 덩어리의 타동사라 수동태에서도 after를 남겨 was looked after by가 된다.\n\n보기 비교: at을 넣으면 look at(보다)이 되어 뜻이 달라지고, 전치사를 빼면 by 앞이 비어 틀린다.\n\n기억 연결: look after · take care of · laugh at → 수동에서도 전치사 그대로."},
  {"n":51,"point":"the number of + 단수동사 / a number of + 복수동사","lesson":"agreement-quantity","type":"text","question":"“그 도시의 자전거 이용자 수가 늘고 있다.”\nThe number of cyclists in the city [are] growing.\n대괄호 부분을 한 단어로 고쳐 쓰세요.","answers":["is"],"explanation":"정답 근거: The number of + 복수명사는 “~의 수”라 주어 number가 단수이므로 are를 is로 고친다.\n\n보기 비교: cyclists(복수)에 맞춘 are는 A number of(많은 ~)일 때의 수일치다.\n\n기억 연결: The number of → is / A number of → are."},
  {"n":52,"point":"부분 표현(percent/half/most of) + 명사에 수일치","lesson":"agreement-quantity","type":"text","question":"“우리 반 학생의 절반이 감기에 걸렸다.”\nHalf of the students in my class [has] caught a cold.\n대괄호 부분을 한 단어로 고쳐 쓰세요.","answers":["have"],"explanation":"정답 근거: Half of 뒤의 명사 the students가 복수이므로 동사도 복수 have로 고친다.\n\n보기 비교: class(단수)는 in my class라는 수식어 안의 명사라 기준이 아니다.\n\n기억 연결: half · most · percent of + 명사 → of 바로 뒤 명사가 동사를 정한다."},
  {"n":53,"point":"one of the + 복수명사 + 단수동사","lesson":"agreement-quantity","type":"text","question":"“내 가장 친한 친구들 중 한 명이 다음 달에 결혼한다.”\nOne of my best friends [are] getting married next month.\n대괄호 부분을 한 단어로 고쳐 쓰세요.","answers":["is"],"explanation":"정답 근거: 주어는 One이고 of my best friends는 수식어라 단수동사 is로 고친다.\n\n보기 비교: 가까운 복수명사 friends에 맞춘 are는 틀린다.\n\n기억 연결: One of the(my) + 복수명사 + 단수동사."},
  {"n":54,"point":"there 구문(there seem(s) to be) 수일치","lesson":"agreement-subject","type":"text","question":"“그 계획에는 몇 가지 문제가 있는 것 같다.”\nThere [seems] to be a few problems with the plan.\n대괄호 부분을 한 단어로 고쳐 쓰세요.","answers":["seem","appear"],"explanation":"정답 근거: there 구문의 동사는 뒤의 진짜 주어 a few problems(복수)에 맞추므로 seems를 seem으로 고친다.\n\n보기 비교: seems는 주어가 단수(a problem)일 때 쓴다.\n\n기억 연결: There seem to be + 복수 / There seems to be + 단수."},
  {"n":55,"point":"긴 수식어 뒤 주어의 수와 태(have been p.p.)","lesson":"agreement-subject","type":"text","question":"“창고에서 위조 시계 수십 상자가 발견되었다.”\nDozens of boxes of fake watches [was found] in the warehouse.\n대괄호 부분을 두 단어로 고쳐 쓰세요.","answers":["were found","have been found","had been found"],"explanation":"정답 근거: 주어의 핵심은 dozens of boxes(복수)이고 of fake watches는 수식어라 was found를 were found로 고친다.\n\n보기 비교: 상자는 “발견된” 것이라 수동은 그대로 두고 수만 맞춘다. found만 쓰면 능동이 되어 틀린다.\n\n기억 연결: 긴 주어 → 수(boxes → were)와 태(발견“된”)를 함께 확인."},
  {"n":56,"point":"재귀대명사 수일치(themselves/itself)","lesson":"pronoun","type":"text","question":"“그 아이들은 이제 스스로 옷을 입을 수 있다.”\nThe children can dress ___ now.\n알맞은 재귀대명사를 한 단어로 쓰세요.","answers":["themselves"],"explanation":"정답 근거: 주어 The children이 복수이므로 재귀대명사도 복수 themselves를 쓴다.\n\n보기 비교: itself나 himself는 단수라 복수 주어와 맞지 않다.\n\n기억 연결: children · birds · they → themselves."},
  {"n":57,"point":"가목적어 it(make it + 형용사 + to do)","lesson":"pronoun","type":"text","question":"“나는 매일 아침 30분씩 걷는 것을 규칙으로 삼는다.”\nI make ___ a rule to walk for thirty minutes every morning.\n빠진 한 단어를 쓰세요.","answers":["it"],"explanation":"정답 근거: make의 진짜 목적어 to walk …가 길어 뒤로 보냈으므로 목적어 자리에 가목적어 it을 둔다.\n\n보기 비교: this나 that은 가목적어로 쓰지 않는다.\n\n기억 연결: make it a rule to do · make it + 형용사 + to do."},
  {"n":58,"point":"불가산명사(information/advice/furniture) 복수 불가","lesson":"noun","type":"text","question":"“그 여행사는 우리에게 유용한 정보를 많이 주었다.”\nThe travel agency gave us a lot of useful [informations].\n대괄호 부분을 한 단어로 고쳐 쓰세요.","answers":["information"],"explanation":"정답 근거: information은 셀 수 없는 명사라 복수형이 없으므로 informations를 information으로 고친다.\n\n보기 비교: 양이 많아도 a lot of · much로 나타내고 -s를 붙이지 않는다.\n\n기억 연결: information · advice · furniture · equipment → -s(X)."},
  {"n":59,"point":"부정부사(Hardly/Never/Rarely) 문두 도치","lesson":"inversion-negation","type":"text","question":"“내가 잠들자마자 초인종이 울렸다.”\nHardly [I had] fallen asleep when the doorbell rang.\n대괄호 부분을 어순을 바꿔 두 단어로 쓰세요.","answers":["had I"],"explanation":"정답 근거: 부정부사 Hardly가 문장 맨 앞에 오면 조동사와 주어를 도치하므로 I had를 had I로 바꾼다.\n\n보기 비교: 평서문 어순 I had는 Hardly가 문두일 때 쓰지 않는다. 짝은 than이 아니라 when이다.\n\n기억 연결: Hardly · Scarcely had + S + p.p. when ~ = “~하자마자”."},
  {"n":60,"point":"부분부정(not always) vs 전체부정(never)","lesson":"inversion-negation","type":"text","question":"“그는 결코 회의에 늦는 법이 없다.”\nHe is [not always] late for meetings.\n우리말 뜻에 맞게 대괄호 부분을 한 단어로 고쳐 쓰세요.","answers":["never"],"explanation":"정답 근거: “결코 ~않다”는 전체부정이므로 not always를 never로 고친다.\n\n보기 비교: not always는 “항상 늦는 것은 아니다(가끔 늦는다)”라는 부분부정이라 우리말과 뜻이 다르다.\n\n기억 연결: 결코 · 전혀 → never / 항상 ~한 것은 아니다 → not always."}
 ];
 // 국어 · 사고의 힘 논리 제1편 — 1장 논증의 개념과 유형(31문제) · 2장 명제 논리(112문제). 모두 4지선다이고 한 줄이 곧 문제 하나다.
 // 교재 문장·예문은 쓰지 않고 같은 개념을 새 예문으로 만든 원고(research/korean-logic/korean-logic.json)를 한 글자도 바꾸지 않고 옮겼다.
